filterProc:LONG - pointer	to a filter procedure;;     output: itemHit:WORD - ID of item	Hit;_____________________________________________________________________________	ENTRY NoteAlertNoteAlert	PROC	ldx #noteIcon	bra GeneralAlert	ENDP;____________________________________________________________________________;;       CautionAlert;;      input: AlertTemplate:LONG - pointer to the alert template;             filterProc:LONG - pointer	to a filter procedure;;     output: itemHit:WORD - ID of item	Hit;_____________________________________________________________________________	ENTRY CautionAlertCautionAlert	PROC	ldx #cautionIcon	bra GeneralAlert	ENDP;____________________________________________________________________________;;       Alert;;      input: AlertTemplate:LONG - pointer to the alert template;             filterProc:LONG - pointer	to a filter procedure;;     output: itemHit:WORD - ID of item	Hit;_____________________________________________________________________________	ENTRY AlertAlert	PROC	ldx #0	ENDP;____________________________________________________________________________;;       GeneralAlert;;      input: AlertTemplate:LONG - pointer to the alert template;             filterProc:LONG - pointer	to a filter procedure;;             A-reg contains the WAP from dispatcher;             X-reg contains the icon id to use.;;     output: itemHit:WORD - ID of item	Hit;; This is a general alert routine called by the specific alert routines; that are entry points to the dialog manager.  The specific routines; load the x-reg with the icon ID that should be used and preserve; the WAP from the dispatcher.;; Change History;; 4 March 88	STEVEN Glass;; Used WAP instead of calling control manager for WAP;_____________________________________________________________________________	ENTRY GeneralAlertGeneralAlert	PROCtheDialog	equ 0ItemTemplate	equ theDialog+4PortSave	equ ItemTemplate+4Globals	equ PortSave+4StageVector	equ Globals+4IconID	equ StageVector+2IconHandleStruct	equ IconID+2SizeLocals	equ IconHandleStruct+4	tay	; save d-page in y	tlink 8,SizeLocalsfilterProc	equ inputAlertTemplate	equ filterProc+4itemHit	equ output	stx <IconID	; save Icon ID;; Get Dialog Manager Zero Page;	sty <Globals	stz <Globals+2	ldy #HandStruct	lda [<Globals],y	sta <IconHandleStruct	iny	iny	lda [<Globals],y	sta <IconHandleStruct+2;; Is it the same alert as the last alert;	ldy #atalertID	lda [<AlertTemplate],y	ldy #LastAlertID	cmp [<Globals],y	beq GetStage;; If not, set lastalertID to current alert, and reset alert	stage;	sta [<Globals],y	; a = AlertID, y = #LastAlertID	lda #0	ldy #AlertStage	sta [<Globals],y;; Get the current stage of the alert;GetStage		; 	ldy #AlertStage	; calculate offset to current stage	lda [<Globals],y	; in the alert template	clc	adc #atstage1	tay	lda [<AlertTemplate],y	and #$FF	sta <StageVector;; Call the Sound Procedure;	and #%00000011	; get sound number in bits 0-1	pha	ldy #AlertSoundProc+1 ; look if there is a custom sound proc	lda [<Globals],y	; (X = bits 8-23)	dey	; Y = AlertSoundProc	tax	bne CallCustomSound	lda [<Globals],y	; test now low word	bne CallCustomSound	; (A = bits 0-15)	clc	;24-Sep-90 DAL	jsl StdSoundProc	; call standard sound proc	bra CheckDrawnCallCustomSound	lda [<Globals],y	; X already=bits 8-23, Y=AlertSoundProc	clc	;24-Sep-90 DAL	jsl long_call	; and A = low byte of procedure address;; Look if alert box	should be drawn;CheckDrawn	lda <StageVector	and #%10000000	; boxdrawn is bit 7	bne CreateDialog	brl IncAlertStage;; Creates modal dialog for alert by calling DialogFromTemplate;CreateDialog	pushzptr <theDialog	; variable to store	dialog ptr in	pushlongdp <AlertTemplate ; pointer to template	pushword #1	; visible	lda #0	; refcon = 0	pha	pha	lda #atitemlist	; offset to item list	pha	jsl DialogFromTemplate ; create dialog and set error status	bcc AddIcon	; error!, exit	brl exit;; Then add the alert icon;AddIcon	lda <IconID	bne @blark	brl SetDef	; no icon@blark	dec a	; compute index to icon pointer	asl a	asl a	tax;; Assume we're in 640 mode;	lda >Icon640Table,x	; get icon pointer from 640 table	sta [<IconHandleStruct] ; and store in fake handle	lda >Icon640Table+2,x	ldy #2	sta [<IconHandleStruct],y;; See if we are in 320 or 640;	lda [<theDialog]	; get PortSCB	and #$0080	; 0=320, 1=640	bne CreateIcon	lda >Icon320Table,x	; get icon pointer from 320 table	sta [<IconHandleStruct] ; and store in fake handle	lda >Icon320Table+2,x	ldy #2	sta [<IconHandleStruct],yCreateIcon	tsc	; make room on the stack for icon template	sec	sbc #24	tcs	inc a	; store starting address of icon template in x	tax	lda #-32768	; store icon ID	sta iconitemID+1,s	lda #5	; store icon boundaries	sta iconitemRect+1,s*** added 26-Aug-91 DAL -- if 640 and dialog is at odd location, compensate	lda [<theDialog]	and #$0080*** added 13-Oct-91 DAL -- A was supposed to be 20 for 320 mode	php	lda #20	plp*** end 13-Oct-91	beq @1	;320 is no problem	ldy #10	;offset into port of boundsRect.x1	lda [<theDialog],y	lsr a	lda #20	;used to always be 20, now can be 19 instead	bcc @1	;it's even, no problem	dec a*** end 26-Aug-91*** From GeneralAlert to here is duplicated in the ROM 3 patch@1	sta iconitemRect+1+2,s	lda #23	sta iconitemRect+1+4,s	lda #60	sta iconitemRect+1+6,s	lda #IconItem+ItemDisable	sta iconitemType+1,s	lda <IconHandleStruct	sta iconitemDescr+1,s	lda <IconHandleStruct+2	sta iconitemDescr+1+2,s	lda #0	; store icon item value, flag, and ptr to color table	sta iconitemValue+1,s	sta iconitemFlag+1,s	sta iconitemColor+1,s	sta iconitemColor+1+2,s	pushlongdp <theDialog;        pushlong #Icon_Template	pea 0000	; push address of icon template onto stack	txa	pha	_GetNewDItem	; create icon	tsc	; remove icon template space from stack	clc	adc #24	tcs;; Set the default button to what is specified in the alert template;SetDef		; 	lda <StageVector	and #%01000000	; default button ID	minus 1 is bit 6	beq CallModalDialog;; When dialog is created, default button is ID 1. If alert defbutID bit is; set, must change dialog default button to ID 2 (Cancel).;	pushword #2	pushlongdp <theDialog	_SetDefButtonCallModalDialog		; 	pha	; space for itemHit	output	pushlongdp <filterProc	_ModalDialog	pla	sta <itemHit;; And dispose of dialog;	pushlongdp <theDialog	_CloseDialog;; Increment Alert Stage if not already maximum (3);IncAlertStage	ldy #AlertStage	lda [<Globals],y	cmp #3	bge noerror	inc a	sta [<Globals],ynoerror	lda #0exit	tunlink	rtl	ENDP;_____________________________________________________________________________;;        GetAlertStage;;       input: none;;      output: CurAlertStage:WORD - current stage of alert;_______________________________________________________________________________	ENTRY GetAlertStageGetAlertStage	PROC	ldy #AlertStage	jmp getWORDfromZP	ENDP;_____________________________________________________________________________;;        ResetAlertStage;;       input: none;;      output: none;; Change History;; 4 March 88	Steven Glass;; Changed to use the WAP instead of calling the Control manager for the ; direct page value.;______________________________________________________________________________	ENTRY ResetAlertStageResetAlertStage	PROC;; Save original zero page;	phd	tcd	stz <AlertStage;; Restore original zero page;	pld	lda #0	clc	rtl	ENDP;            copy  NewItem.asm; NewItem.asm		Jean-Charles Mourey	TITLE 'New Item Procedures';.......................................;;        DefProc Table;.......................................	ENTRY DefProcTableDefProcTable	PROC	DC.L $00000000	DC.L $02000000	DC.L $04000000	DC.L $06000000	DC.L $00000000	; User Control Item, not used here	IMPORT StatTextDefProc	IMPORT LongStatTextDefProc	IMPORT EditLineDefProc	IMPORT IconItemDefProc	IMPORT PicItemDefProc	IMPORT UserItemDefProc	DC.L StatTextDefProc	DC.L LongStatTextDefProc	DC.L EditLineDefProc	DC.L IconItemDefProc	DC.L PicItemDefProc	DC.L UserItemDefProc	DC.L $00000000	; User Control Item	2, not used here	DC.L LongStatTextDefProc ; DAN H. (added for LongStatText2)	ENDP;______________________________________________________________________________;;        NewDItem;;       input: theDialog:LONG - pointer	to dialog this item	belongs to.;              ItemID:WORD - item identifier for all item -related dlg mgr calls;  rect/point  ItemRect:LONG - display rectangle (or upper-left point twice);              ItemType:WORD - Button, Check, UserCtl, EditText, Pic, UserItem.;              ItemDescr:LONG - stringptr, procptr, iconhandle or pichandle.;              ItemValue:WORD - init value, textlen, maxlen, or 0 or ...;   optional   ItemFlag:WORD - includes	visible/invisible flag (0 for default);   optional   ItemColor:LONG - pointer	to item's color table (0 for default);;      output: none.;;    function: Adds	a new item to the dialog's item list and draws it if it's;              visible.; Really What Happens: Creates a Control (see _NewControl) from the parameters;              passed, the actual drawing is done later by routines such as;              _ModalDialog. (DAN H.);;   ItemType	           ItemDescr                  ItemValue; ----------------------------------------------------------------------------;   Button, Check, RadioItem   title string               init value;   StatText	           static string              0;   LongStatText	           text pointer               text length;   EditLine	           default string             max string length;   ScrollBarItem	           scrollbar itemdef proc     0	or default value;   IconItem	           iconhandle                 0;   PicItem	           pichandle                  0;   UserCtlItem	           control definition proc    init value;   UserItem	           item definition proc       any value you want;   UserCtlItem2	           control additional parms   init value; ----------------------------------------------------------------------------;; IconHandle: handle to an icon.;; ScrollBar ItemDef	Proc:;;              inputs: command (getinitview, getinittotal, getinitvalue, action);	   ScrollBarID;;              output: result (view, total, value or none).;______________________________________________________________________________	ENTRY NewDItemNewDItem	PROCItemControl	equ 0ItemPtr	equ ItemControl+4ItemTypeNum	equ ItemPtr+4defproc	equ ItemTypeNum+2PortSave	equ defproc+4ScrollBarDef	equ PortSave+4LongParam	equ ScrollBarDef+4Title	equ LongParam+4SizeLocals	equ Title+4	tlink 24,SizeLocalsItemColor	equ inputItemFlag	equ ItemColor+4ItemValue	equ ItemFlag+2ItemDescr	equ ItemValue+2ItemType	equ ItemDescr+4ItemRect	equ ItemType+2ItemID	equ ItemRect+4theDialog	equ ItemID+2;; Clear LongParam (Param1/Param2 for NewControl);	stz <LongParam	stz <LongParam+2;; Set Current port = our dialog;	pha	; space for port pointer	pha	_GetPort	pulllong <PortSave	pushlongdp <theDialog	_SetPort	lda #0	; set origin to 0,0	pha	pha	_SetOrigin;; Check ItemType;	lda <ItemType	and #$7FFF	; get rid of ItemDisable bit	sta <ItemTypeNum	cmp #ButtonItem	bge TestSup	brl badtypeTestSup		; 	cmp #MaxItemType+1	blt TestUserCtl	brl badtype;; User Control Item	is a little bit special;TestUserCtl		; 	cmp #UserCtlItem	bne isUserCtl2	movelong <ItemDescr,<defproc	movelong #EmptyString,<ItemDescr	bra CallNewControl;; User Control Item	2 is even more special;isUserCtl2		; 	cmp #UserCtlItem2	bne isScrollBar	movelong [<ItemDescr],DefProcParm,<defproc	movelong [<ItemDescr],ParamLong,<LongParam	movelong [<ItemDescr],TitleParm,<Title	movelong <Title,<ItemDescr	bra CallNewControl;; Scroll Bar item is very special;isScrollBar		; 	cmp #ScrollBarItem	bne isButton	movelong <ItemDescr,<ScrollBarDef	movelong #EmptyString,<ItemDescr	bra isOther;; Thick outline for	default button;isButton		; 	cmp #ButtonItem	bne isOther	ldy #defbutID-wport	lda [<theDialog],y	cmp <ItemID	bne isOther	lda <ItemFlag	; if the button is the default button	ora #BOLD_BUTT	; create it with a thick outline	sta <ItemFlagisOther		; 	lda <ItemTypeNum	sec	sbc #ButtonItem	asl a	asl a	tax	lda >DefProcTable,x	sta <defproc	lda >DefProcTable+2,x	sta <defproc+2CallNewControl		; 	pha	; space for control	handle	pha	pushlongdp <theDialog	pushlongdp <ItemRect	pushlongdp <ItemDescr	; contains CtrlData	or empty string	pushworddp <ItemFlag	lda <ItemTypeNum	cmp #ScrollBarItem	beq CallScrollBarProcedure	pushworddp <ItemValue	pushlongdp <LongParam	; Param1, Param2	brl pushotherparmsCallScrollBarProcedure	; ;; Check that ScrollBarDef is non zero before to call it;	lda <ScrollBarDef	bne CheckNotNeg	lda <ScrollBarDef+2	beq DefaultValues;; Check that ScrollBarDef is not negative before to call it	(autoTrack feature);CheckNotNeg		; 	lda <ScrollBarDef+2	bmi DefaultValues;; Get the init values for the Scroll Bar from the Scroll Bar defproc;CallScrollBarDef		; 	pha	; space for result	pushword #getinitvalue ; get init value	pushlongdp <theDialog	pushworddp <ItemID	lda <ScrollBarDef	ldx <ScrollBarDef+1	jsl long_call	; starting value is	on stack	pha	; space for result	pushword #getinitview ; get init view	pushlongdp <theDialog	pushworddp <ItemID	lda <ScrollBarDef	ldx <ScrollBarDef+1	jsl long_call	; view size is on stack	pha	; space for result	pushword #getinittotal ; get init total	pushlongdp <theDialog	pushworddp <ItemID	lda <ScrollBarDef	ldx <ScrollBarDef+1	jsl long_call	; data size is on stack	bra pushotherparms;; If ScrollBarDef is 0 or negative, put	default values in view, total and value;DefaultValues	pushworddp <ItemValue	pushword #10	pushword #300pushotherparms		; 	pushlongdp <defproc	; control defproc	pushworddp <ItemType	; Hiword RefCon = ItemType	pushworddp <ItemID	; Loword RefCon = ItemID	pushlongdp <ItemColor	_NewControl	pulllong <ItemControl	lda #0	ldx <ItemControl	bne ItemOk	ldx <ItemControl+2	bne ItemOkbadtype		; 	lda #DLGERR+NewItemFailed	bra ExitNewDItemItemOk		; 	ldx <ItemTypeNum	cpx #ScrollBarItem	bne ExitNewDItem;; Add a new field to the Scroll Bar Control Record (the ScrollBarDef procedure);ScrollItemOk		; 	pushlong #ScrollBarSIZE ; expand the scroll bar record	pushlongdp <ItemControl	_SetHandleSize	bcs MmgrError	; error, exit;; Copy the Scroll Bar description parameter into this field;	movelong [<ItemControl],0,<ItemPtr ; get pointer to control	lda <ScrollBarDef	; put the scroll bar defproc	ldy #iScrollBarDef	; in the additional	field.	sta [<ItemPtr],y	lda <ScrollBarDef+2	iny	iny	sta [<ItemPtr],y	lda #0	; no error	bra ExitNewDItemMmgrError		; 	pha	; save Mmgr error code	pushlongdp <ItemControl	_DisposeControl	plaExitNewDItem		; 	pha	; save error code;; Restore previous port;	pushlongdp <PortSave	_SetPort	pla	; restore error code	tunlink	rtl	ENTRY EmptyStringEmptyString	DC.B 1	DC.B ' '	ENDP;____________________________________________________________________________;;        SetItemToControl;;      input:  theControl:LONG;              ItemID:WORD;;    function: Given a control, make it	a UserCtlItem;____________________________________________________________________________	ENTRY SetItemToControlSetItemToControl	PROCControlPtr	equ 0SizeLocals	equ ControlPtr+4	tlink 6,SizeLocalsItemID	equ inputTheControl	equ ItemID+2	movelong [<theControl],0,<ControlPtr	lda #UserCtlItem	ldy #iitemtype	sta [<ControlPtr],y	lda <ItemID	ldy #iitemid	sta [<ControlPtr],y	lda #0	ldx #SizeLocals	jmp quit6	ENDP;______________________________________________________________________________;;        RemoveItem;;       input: theDialog:LONG - pointer	to dialog.;              ItemID:WORD - ID of item	to be removed.;;      output: none.;;    function: Erases the given item from the screen and removes it from the;              dialog's item list.;______________________________________________________________________________	ENTRY RemoveItemRemoveItem	PROCPortSave	equ 0Control	equ PortSave+4SizeLocals	equ Control+4	tlink 6,SizeLocalsItemID	equ inputtheDialog	equ ItemID+2;; Get handle to control item:;	pha	; space for control	handle	pha	pushlongdp <theDialog	pushworddp <ItemID	_GetControlDItem	Check_Error notFound	pulllong <Control;; Set Current port = our dialog;	pha	; space for port pointer	pha	_GetPort	pulllong <PortSave	pushlongdp <theDialog	_SetPort	lda #0	pha	pha	_SetOrigin;; If Item to remove	is current EditLine	item, make the next	EditLine item; the current one. If no more EditLine item, set the current one to 0.;	ldy #edittextID-wport	lda [<theDialog],y	cmp <ItemID	bne DisposeIt	lda #0	; clear it	sta [<theDialog],y	pha	; get next EditLine	item	pushlongdp <theDialog	pushlongdp <Control	jsl FindNextEditLine	plx	cpx <ItemID	; if another one, set it the current one	beq DisposeIt	pushlongdp <theDialog	phx	pushword #0	pushword #32767	_SelITextDisposeIt		; 	pushlongdp <Control	; First hide control	_HideControl	pushlongdp <Control	; Dispose of control	_DisposeControl	pha	; save error code	pushlongdp <PortSave	_SetPort	pla	; restore error codequickexit		; 	ldx #SizeLocals	jmp quit6notFound		; 	plx	plx	bra quickexit	ENDP;______________________________________________________________________________;;        GetNewDItem;;       input: theDialog:LONG - pointer	to the dialog port;              ItemTemplate:LONG - pointer to the item template;;      output: none;______________________________________________________________________________	ENTRY GetNewDItemGetNewDItem	PROC	tlink 8ItemTemplate	equ inputtheDialog	equ ItemTemplate+4	pushlongdp <theDialog	ldy #ititemID	; itemID	lda [<ItemTemplate],y	pha	lda <ItemTemplate	; itemRect	clc	adc #ititemRect	tax	lda <ItemTemplate+2	adc #0	pha	phx	ldy #ititemType	; itemType	lda [<ItemTemplate],y	pha	pushlong [<ItemTemplate],ititemDescr ; itemDescr	ldy #ititemValue	; itemValue	lda [<ItemTemplate],y	pha	iny	; itemFlag	iny	lda [<ItemTemplate],y	pha	pushlong [<ItemTemplate],ititemColor ; itemColor	_NewDItem	ldx #0	jmp quit8	ENDP;            copy  GetItem.asm; GetItem.asm		Jean-Charles Mourey	TITLE 'Get and Set Item Procedures';_____________________________________________________________________________;;        GetControlDItem;;       input: theDialog:LONG - pointer	to the dialog port.;              itemID:WORD - ID number uniquely identifying	the item.;;      output: item:LONG - controlhandle to the item.;;    function: given an item number in a dialog, returns the control handle;              to this item.;______________________________________________________________________________	ENTRY GetControlDItemGetControlDItem	PROCCurItemHdl	equ 0CurItemPtr	equ CurItemHdl+4CurID	equ CurItemPtr+4SizeLocals	equ CurID+2	tlink 6,SizeLocalsItemID	equ inputtheDialog	equ ItemID+2item	equ output;; Initializes item to NIL;	stz <item	stz <item+2;; Get First Item from Control List;	movelong [<theDialog],wcontrol-wport,<CurItemHdl;; if CurItem is NIL, exit;NextItem		; 	lda <CurItemHdl	bne TestCurItem	lda <CurItemHdl+2	bne TestCurItem	lda #DLGERR+ItemNotFound	bra exit;; Read ID of current item, and compare it to the given ID;TestCurItem		; 	movelong [<CurItemHdl],0,<CurItemPtr ; get pointer to item	ldy #iitemid	; get item ID	lda [<CurItemPtr],y	cmp <ItemID	; compare it to given ID	beq found	; found it	movelong [<CurItemPtr],0,<CurItemHdl ; get next item handle	bra NextItemfound		; 	movelong <CurItemHdl,<item	lda #0exit		; 	ldx #SizeLocals	jmp quit6	ENDP;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        GetItemWORD;;       input: theDialog:LONG;              itemID:WORD;              Y register = which field	in Control Record (offset);;      output: itemResult:WORD	returns content of field (size = WORD);;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY GetItemWORDGetItemWORD	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 6,SizeLocalsitemID	equ inputtheDialog	equ itemID+2itemResult	equ output	phy	; save field offset	pha	; space for control	handle	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	bcs notFound	pulllong <Control	movelong [<Control],0,<ControlPtr	ply	; restore field offset	lda [<ControlPtr],y	sta <itemResult	lda #0exit		; 	ldx #SizeLocals	jmp quit6notFound		; 	plx	plx	plx	; get field offset off stack, 5/16/88 HY	bra exit	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        SetItemWORD;;       input: itemWORD:WORD	word value to set field to in Control;              theDialog:LONG;              itemID:WORD;              Y register = field offset in Control record;;      output: none;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY SetItemWORDSetItemWORD	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 8,SizeLocalsitemID	equ inputtheDialog	equ itemID+2itemWORD	equ theDialog+4	phy	; save field offset	pha	; space for control	record	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	bcs notFound	pulllong <Control	movelong [<Control],0,<ControlPtr	ply	; restore field offset	lda <itemWORD	sta [<ControlPtr],y	lda #0exit		; 	ldx #SizeLocals	jmp quit8notFound		; 	plx	plx	plx	; get field offset off stack, 5/16/88 HY	bra exit	ENDP;_____________________________________________________________________________;;        GetItemType;;       input: theDialog:LONG;              itemID:WORD;;      output: itemType:WORD - including disable bit;______________________________________________________________________________	ENTRY GetItemTypeGetItemType	PROC	ldy #iitemtype	jmp GetItemWORD	ENDP;_____________________________________________________________________________;;        SetItemType;;       input: itemType:WORD - including disable bit;              theDialog:LONG;              itemID:WORD;;      output: none;______________________________________________________________________________	ENTRY SetItemTypeSetItemType	PROC	ldy #iitemtype	jmp SetItemWORD	ENDP;_____________________________________________________________________________;;        GetItemBox;;       input: theDialog:LONG;              itemID:WORD;              itemBox:LONG - pointer to space to store the	enclos. rectangle in;;      output: none;______________________________________________________________________________	ENTRY GetItemBoxGetItemBox	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 10,SizeLocalsitemBox	equ inputitemID	equ itemBox+4theDialog	equ itemID+2	pha	; space for control	record	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	bcs notFound	pulllong <Control	movelong [<Control],0,<ControlPtr	ldy #CtrlRect	lda [<ControlPtr],y	sta [<itemBox]	ldy #CtrlRect+2	lda [<ControlPtr],y	ldy #2	sta [<itemBox],y	ldy #CtrlRect+4	lda [<ControlPtr],y	ldy #4	sta [<itemBox],y	ldy #CtrlRect+6	lda [<ControlPtr],y	ldy #6	sta [<itemBox],y	lda #0exit		; 	ldx #SizeLocals	jmp quit10notFound		; 	plx	plx	bra exit	ENDP;_____________________________________________________________________________;;        SetItemBox;;       input: theDialog:LONG;              itemID:WORD;              itemBox:LONG - pointer to the enclosing rectangle;;      output: none;______________________________________________________________________________	ENTRY SetItemBoxSetItemBox	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 10,SizeLocalsitemBox	equ inputitemID	equ itemBox+4theDialog	equ itemID+2	pha	; space for control	handle	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	bcs notFound	pulllong <Control;; Hide control from	previous location;	pushlongdp <Control	_HideControl;; Change item rectangle to new rectangle;	movelong [<Control],0,<ControlPtr	lda [<itemBox]	ldy #CtrlRect	sta [<ControlPtr],y	ldy #2	lda [<itemBox],y	ldy #CtrlRect+2	sta [<ControlPtr],y	ldy #4	lda [<itemBox],y	ldy #CtrlRect+4	sta [<ControlPtr],y	ldy #6	lda [<itemBox],y	ldy #CtrlRect+6	sta [<ControlPtr],y;; Redraws control at new location;	pushlongdp <Control	_ShowControl;; Returns no error (never fails!);	lda #0exit		; 	ldx #SizeLocals	jmp quit10notFound		; 	plx	plx	bra exit	ENDP;_____________________________________________________________________________;;        GetFirstItem;;       input: theDialog:LONG;;      output: firstItem:WORD - ID of first item, zero if no item in dialog;______________________________________________________________________________	ENTRY GetFirstItemGetFirstItem	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 4,SizeLocalstheDialog	equ inputfirstItem	equ output	movelong [<theDialog],wcontrol-wport,<Control ; get first control	lda <Control	bne notempty	lda <Control+2	bne notempty	stz <firstItem	lda #DLGERR+ItemNotFound	bra exitnotempty		; 	movelong [<Control],0,<ControlPtr ; Get	its ID	moveword [<ControlPtr],iitemID,<firstItem	lda #0exit		; 	ldx #SizeLocals	jmp quit4	ENDP;_____________________________________________________________________________;;        GetNextItem;;       input: theDialog:LONG;              itemID:WORD - ID of current item;;      output: nextItem:WORD - ID of next item, zero if last item;______________________________________________________________________________	ENTRY GetNextItemGetNextItem	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 6,SizeLocalsitemID	equ inputtheDialog	equ itemID+2nextItem	equ output	pha	; space for control	handle	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	bcs notFound	pulllong <Control	movelong [<Control],0,<ControlPtr 	; dereference control 	movelong [<ControlPtr],0,<Control 	; get next handle of next control	lda <Control+1	; check if this handle is valid	bne notLastControl	; if zero than last control in list	sta <nextItem	; return result of zero for no more items in list	bra exit1notLastControl	movelong [<Control],0,<ControlPtr 	; deref the control of item we want		moveword [<ControlPtr],iitemID,<nextItem ; return id of controlexit1	lda #0exit2		; 	ldx #SizeLocals	jmp quit6notFound		; 	stz <nextItem	; no other item in list	plx	plx	bra exit2	ENDP;_____________________________________________________________________________;;        GetItemFlag;;       input: theDialog:LONG;              itemID:WORD;;      output: itemFlag:WORD - Flag of item in lo byte;______________________________________________________________________________;GetItemFlag START;         using ctrlstruct;         using dialogstruct;;Control        equ	   0;ControlPtr     equ	   Control+4;SizeLocals     equ	   ControlPtr+4;;         tlink  8,SizeLocals;;itemID         equ	   input;theDialog      equ	   itemID+2;;itemFlag       equ	   output;;         pha		        ; space for	control handle;         pha;         pushlongdp <theDialog;         pushworddp <itemID;         _GetControlDItem;         bcs   notFound;         pulllong <Control;;         movelong [<Control],0,<ControlPtr;       ;         ldy   #CtrlFlag;         lda   [<ControlPtr],y;         and   #$FF	        ; get CtrlFlag byte;         sta   <itemFlag;;         lda   #0;exit     anop;         ldx   #SizeLocals;         jmp   quit8;;notFound anop;         plx;         plx;         bra   exit;;         END;;;_____________________________________________________________________________;;        SetItemFlag;;       input: itemFlag:WORD - new flag	for item;              theDialog:LONG;              itemID:WORD;;      output: none;______________________________________________________________________________;SetItemFlag START;         using ctrlstruct;         using dialogstruct;;Control        equ	   0;ControlPtr     equ	   Control+4;SizeLocals     equ	   ControlPtr+4;;         tlink  10,SizeLocals;;itemID         equ	   input;theDialog      equ	   itemID+2;itemFlag       equ	   theDialog+4;;         pha		        ; space for	control handle;         pha;         pushlongdp <theDialog;         pushworddp <itemID;         _GetControlDItem;         bcs   notFound;         pulllong <Control;;         movelong [<Control],0,<ControlPtr;       ;         ldy   #CtrlFlag;         lda   [<ControlPtr],y;         and   #$FF00	        ; preserves	CtrlHilite byte;         ora   <itemFlag;         sta   [<ControlPtr],y;;         lda   #0;exit     anop;         ldx   #SizeLocals;         jmp   quit10;;notFound anop;         plx;         plx;         bra   exit;;         END;;_____________________________________________________________________________;;        GetItemValue  (in ToolBox Ref. call is GetDItemValue);;       input: theDialog:LONG;              itemID:WORD;;      output: itemValue:WORD - Value of item;______________________________________________________________________________	ENTRY GetItemValueGetItemValue	PROC	tlink 6itemID	equ inputtheDialog	equ itemID+2itemValue	equ output;; push space for GetCtlValue result;	pha;; Get Control Handle to item;	pha	; space for control	handle	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	; control handle is	on stack	bcs notFound;; Get Control Value;	_GetCtlValue	pullword <itemValue	lda #0exit		; 	ldx #0	jmp quit6notFound		;	plx	; get handle off stack from _GetControlDItem call 	plx	plx	; pull extra word on stack initially put on stack for		; _GetCtlValue call (5/2/88 HY)	bra exit		ENDP;_____________________________________________________________________________;;        SetItemValue;;       input: itemValue:WORD - new value for item;              theDialog:LONG;              itemID:WORD;;      output: none;______________________________________________________________________________	ENTRY SetItemValueSetItemValue	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 8,SizeLocalsitemID	equ inputtheDialog	equ itemID+2itemValue	equ theDialog+4	pushworddp <itemValue	; push value for SetCtlValue	pha	; space for control	handle	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	; control handle is	on stack	bcs notFound	lda 1,s	; get control value	but does not	sta <Control	; pull it from stack	lda 3,s	sta <Control+2	_SetCtlValue	; redraws control (if value changed)exit		;	        ; returns SetCtlValue error	ldx #SizeLocals	jmp quit8notFound		; 	plx	plx	plx	; get value for SetCtlValue off stack	bra exit	ENDP;_____________________________________________________________________________;;        GetItemColor;;       input: theDialog:LONG;              itemID:WORD;;      output: itemColor:LONG - pointer	to color table;______________________________________________________________________________;GetItemColor START;         using ctrlstruct;         using dialogstruct;;Control        equ	   0;ControlPtr     equ	   Control+4;SizeLocals     equ	   ControlPtr+4;;         tlink 6,SizeLocals;;itemID         equ	   input;theDialog      equ	   itemID+2;;itemColor      equ	   output;;         pha		 ; space for control handle;         pha;         pushlongdp <theDialog;         pushworddp <itemID;         _GetControlDItem;         bcs   notFound;         pulllong <Control;;         movelong [<Control],0,<ControlPtr;;         movelong [<ControlPtr],CtrlColor,<itemColor;;         lda   #0;exit     anop;         ldx   #SizeLocals;         jmp   quit6;;notFound anop;         plx;         plx;         bra   exit;;         END;;_____________________________________________________________________________;;        SetItemColor;;       input: itemColor:LONG - pointer	to new color table;              theDialog:LONG;              itemID:WORD;;      output: none;______________________________________________________________________________;SetItemColor START;         using ctrlstruct;         using dialogstruct;;Control        equ	   0;ControlPtr     equ	   Control+4;SizeLocals     equ	   ControlPtr+4;;         tlink 10,SizeLocals;;itemID         equ	   input;theDialog      equ	   itemID+2;itemColor      equ	   theDialog+4;;         pha		 ; space for control handle;         pha;         pushlongdp <theDialog;         pushworddp <itemID;         _GetControlDItem;         bcs   notFound;         pulllong <Control;;         movelong [<Control],0,<ControlPtr;;         lda   <itemColor;         ldy   #CtrlColor;         sta   [<ControlPtr],y;;         lda   <itemColor+2;         ldy   #CtrlColor+2;         sta   [<ControlPtr],y;;         lda   #0;exit     anop;         ldx   #SizeLocals;         jmp   quit10;;notFound anop;         plx;         plx;         bra   exit;;         END;______________________________________________________________________________;;        GetDefButton;;       input: theDialog:LONG - pointer	to the dialog port;;      output: DefBut:WORD - ID of default button;______________________________________________________________________________	ENTRY GetDefButtonGetDefButton	PROC	tlink 4theDialog	equ inputDefBut	equ output	ldy #defbutID-wport	lda [<theDialog],y	sta <DefBut	lda #0	ldx #0	; no locals	jmp quit4	ENDP;______________________________________________________________________________;;        SetDefButton;;       input: DefBut:WORD - ID of new default button;              theDialog:LONG - pointer	to the dialog port;;      output: none;______________________________________________________________________________	ENTRY SetDefButtonSetDefButton	PROCOldControl	equ 0	; old default buttonControl	equ OldControl+4	; new default buttonControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 6,SizeLocalstheDialog	equ inputDefBut	equ theDialog+4;; If there is a current default button,	remove the thick-outline;;; Get the old default button control;	pha	; space for control	handle	pha	pushlongdp <theDialog	ldy #defbutID-wport	lda [<theDialog],y	pha	_GetControlDItem	pulllong <OldControl;; Get the new default button control. If doesn't exist, exit directly;	pha	; space for control	handle	pha	pushlongdp <theDialog	pushworddp <DefBut	_GetControlDItem	Check_Error notFound	pulllong <Control	lda <OldControl	bne RemoveThick	lda <OldControl+2	beq SetNewDefaultRemoveThick		; 	movelong [<OldControl],0,<ControlPtr	ldy #CtrlFlag	lda [<ControlPtr],y	and #NO_BOLD_BUTT	; NO_BOLD_BUTT = not BOLD_BUTT	sta [<ControlPtr],y;; Redraws the control;	pushlongdp <OldControl	_HideControl	pushlongdp <OldControl	_ShowControl;; Set new default button and make it boldly-outlined;SetNewDefault		; 	lda <DefBut	ldy #defbutID-wport	sta [<theDialog],y	movelong [<Control],0,<ControlPtr	ldy #CtrlFlag	lda [<ControlPtr],y	ora #BOLD_BUTT	sta [<ControlPtr],y;; Redraws new default button;	pha	; space for title	pha	pushlongdp <Control	_GetCtlTitle	; title is on the stack	pushlongdp <Control	_SetCtlTitle	lda #0exit		; 	ldx #SizeLocals	jmp quit6notFound		; 	plx	plx	bra exit	ENDP;_____________________________________________________________________________;;        HideDItem;;       input: theDialog:LONG - pointer	to the dialog port;              itemID:WORD - ID of item	to hide;;      output: none;______________________________________________________________________________	ENTRY HideDItemHideDItem	PROC	ldx #0	bra ShowHideDItem	ENDP;_____________________________________________________________________________;;        ShowDItem;;       input: theDialog:LONG - pointer	to the dialog port;              itemID:WORD - ID of item	to show;;      output: none;______________________________________________________________________________	ENTRY ShowDItemShowDItem	PROC	ldx #1	ENDP;_____________________________________________________________________________;;        ShowHideDItem;;       input: theDialog:LONG - pointer	to the dialog port;              itemID:WORD - ID of item	to show/hide;              X register = TRUE if show, FALSE if hide;;      output: none;______________________________________________________________________________	ENTRY ShowHideDItemShowHideDItem	PROC	tlink 6itemID	equ inputtheDialog	equ itemID+2	phx	; save show/hide flag	pha	; space for control	handle	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	bcs notFound	lda 5,s	; get show/hide flag	beq HideIt	_ShowControl	; the Control is on	the stack;		; return ShowControl error status	bra quititHideIt		; 	_HideControl	; the Control is on	the stack;		; return HideControl Error Statusquitit		; 	plx	; pull show/hide flagexit		; 	ldx #0	; no locals	jmp quit6notFound		; 	plx	; get rid of handle from _GetControlDItem call that	plx	; just failed	plx	; pull show/hide flag (5/2/88 HY)	bra exit	ENDP;_____________________________________________________________________________;;        FindDItem;;       input: theDialog:LONG - pointer	to the dialog port;              Point:LONG - point in global coordinates (passed as long);;      output: itemID:WORD - ID of item	located at Point, zero if none;______________________________________________________________________________	ENTRY FindDItemFindDItem	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 8,SizeLocalsPoint	equ inputtheDialog	equ Point+4itemID	equ output	stz <itemID	pha	; space for location result	pushzptr Control	pushlongdp <Point	pushlongdp <theDialog	_FindControl	pla	; if no item hit, return 0 in itemID	beq exit	movelong [<Control],0,ControlPtr ; else	return ID of item hit	moveword [<ControlPtr],iitemid,<itemIDexit		; 	lda #0	ldx #SizeLocals	jmp quit8	ENDP;_____________________________________________________________________________;;        DisableDItem;;       input: theDialog:LONG - pointer	to the dialog port;              itemID:WORD - ID of item	to disable;;      output: none;______________________________________________________________________________	ENTRY DisableDItemDisableDItem	PROC	ldx #0	bra EnableDisableItem	ENDP;_____________________________________________________________________________;;        EnableDItem;;       input: theDialog:LONG - pointer	to the dialog port;              itemID:WORD - ID of item	to enable;;      output: none;______________________________________________________________________________	ENTRY EnableDItemEnableDItem	PROC	ldx #1	ENDP;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        EnableDisableItem;;       input: theDialog:LONG - pointer	to the dialog port;              itemID:WORD - ID of item	to enable/disable;              X register = TRUE if enable, FALSE if disable;;      output: none;;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY EnableDisableItemEnableDisableItem	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 6,SizeLocalsitemID	equ inputtheDialog	equ itemID+2	phx	; save disable/enable flag	pha	; space for control	handle	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	bcs notFound	pulllong <Control	movelong [<Control],0,<ControlPtr	ldy #iitemtype	; read item type	lda [<ControlPtr],y	plx	; get disable/enable flag	beq DisableIt	and #$7FFF	; enable it	bra storeitbackDisableIt		; 	ora #ItemDisable	; disable itstoreitback		; 	sta [<ControlPtr],y	lda #0exit		; 	ldx #SizeLocals	jmp quit6notFound		; 	plx	; first get handle from _GetControlDItem call off stack	plx	plx	; get rid of disable/enable flag	bra exit	ENDP;            copy  DText.asm; DText.asm		Jean-Charles Mourey	TITLE 'Get and Set Text procedures';____________________________________________________________________________;;        GetIText;;       input: theDialog:LONG - pointer	to the dialog;              itemID:WORD - ID of item	in dialog;              theString:LONG - pointer	to a string to put the text in;;      output: none;____________________________________________________________________________	ENTRY GetITextGetIText	PROCControl	equ 0ControlPtr	equ Control+4SourceString	equ ControlPtr+4hLE	equ SourceString+4ptrLE	equ hLE+4TextHandle	equ ptrLE+4TextPtr	equ TextHandle+4SizeLocals	equ TextPtr+4	tlink 10,SizeLocalstheString	equ inputitemID	equ theString+4theDialog	equ itemID+2	pha	; space for control	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	Check_Error notFound	pulllong <Control	movelong [<Control],0,<ControlPtr	ldy #iitemtype	lda [<ControlPtr],y	and #$7FFF	; get rid of ItemDisable Bit	cmp #EditLine	beq GetEditText	cmp #StatText	beq GetStatText	lda #0	; not EditLine or StatText	sta [<theString]	; clear theString	lda #DLGERR+BadItemType ; return error message	brl exitGetStatText		; 	movelong [<ControlPtr],CtrlData,<SourceString	lda [<SourceString]	beq StatTextEmpty	and #$FF	tay	sep #$20	; switch to 8 bit m	longa offcharloop1		; 	lda [<SourceString],y	sta [<theString],y	dey	bpl charloop1StatTextEmpty		; 	lda [<SourceString]	sta [<theString]	rep #$20	; back to 16 bit m	longa on	brl noErrExitGetEditText		; 	movelong [<ControlPtr],CtrlData,<hLE	movelong [<hLE],0,<ptrLE	movelong [<ptrLE],0,<TextHandle	movelong [<TextHandle],0,<TextPtr	ldy #4	; length field	lda [<ptrLE],y	sep #$20	; switch to 8 bit mode	longa off	beq EditTextEmpty	tay	tax	; get a copy of the	length in X	dey	; y equals the length of the string minus the length bytecharloop2		; 	lda [<TextPtr],y	; load accumulator with the yth character	iny	; increment y to allow for length byte	sta [<theString],y	dey	dey	bpl charloop2	txa	; copy length in theStringEditTextEmpty		; 	sta [<theString]	rep #$20	; back to 16 bit m	longa onnoErrExit		; 	lda #0exit		; 	ldx #SizeLocals	jmp quit10notFound		; 	plx	plx	bra exit	ENDP;______________________________________________________________________________;;        SetIText;;       input: theDialog:LONG - dialog port pointer;              itemID:WORD - ID of item	in dialog;              theString:LONG - pointer	to the string;;      output: none;______________________________________________________________________________	ENTRY SetITextSetIText	PROCControl	equ 0ControlPtr	equ Control+4hLE	equ ControlPtr+4TextPtr	equ hLE+4SizeLocals	equ TextPtr+4	tlink 10,SizeLocalstheString	equ inputitemID	equ theString+4theDialog	equ itemID+2	pha	; space for control	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	Check_Error notFound	pulllong <Control	movelong [<Control],0,<ControlPtr	ldy #iitemtype	lda [<ControlPtr],y	and #$7FFF	; get rid of ItemDisable Bit	cmp #EditLine	beq SetEditText	cmp #StatText	beq SetStatText	lda #DLGERR+BadItemType ; return error message	brl exit	; not Text Type item, exitSetStatText		; text of stattext = title of control	pushlongdp <theString	pushlongdp <Control	_SetCtlTitle	brl exitSetEditText		; ;; Get Line Edit Record Handle;	movelong [<ControlPtr],CtrlData,<hLE;; Call LESetSelect,	and redraws the item if no error;	add4 <theString,#1,<TextPtr ; TextPtr	pushlongdp <TextPtr	lda [<theString]	; Length	and #$FF	pha	pushlongdp <hLE	_LESetText	; LESetText does not redraw	bcs exit	; exit if error	pushlongdp <hLE	; redraws the control	pushlongdp <Control	_SetCtlTitle	; returns SetCtlTitle error statusexit		; 	ldx #SizeLocals	jmp quit10notFound		; 	plx	plx	bra exit	ENDP;_____________________________________________________________________________;;        SelIText;;       input: theDialog:LONG - pointer	to the dialog port;              itemID:WORD - ID of item	in dialog;              startSel:WORD - start of	selection;              endSel:WORD - end of selection;;      output: none;______________________________________________________________________________	ENTRY SelITextSelIText	PROColdEditLine	equ 0Control	equ oldEditLine+4ControlPtr	equ Control+4hLE	equ ControlPtr+4	; Line Edit Record for selected ItemSizeLocals	equ hLE+4	tlink 10,SizeLocalsendSel	equ inputstartSel	equ endSel+2itemID	equ startSel+2theDialog	equ itemID+2;; Get handle to item;	pha	; space for control	pha	pushlongdp <theDialog	pushworddp <itemID	_GetControlDItem	Check_Error notFound	pulllong <Control	movelong [<Control],0,<ControlPtr	ldy #iitemtype	lda [<ControlPtr],y	and #$7FFF	cmp #EditLine	beq SelIt	lda #DLGERR+BadItemType	brl quickexit;; Set the port to our dialog;SelIt		; 	pha	; space for port pointer	pha	_GetPort	; saved port is on stack	pushlongdp <theDialog	_SetPort	lda #0	pha	pha	_SetOrigin;; Call LESetSelect to highlight selection;	movelong [<Control],0,<ControlPtr	movelong [<ControlPtr],CtrlData,<hLE ; get Line Edit Handle	pushworddp <startSel	pushworddp <endSel	pushlongdp <hLE	_LESetSelect;; Check if the highlighted EditLine item is the currently active or not;	ldy #edittextID-wport	lda [<theDialog],y	cmp <itemID	bne IsNotActive	brl exitIsNotActive	tax;; If not active, deactivate old (if there is one), and activate new;	pha	; space for control	pha	pushlongdp <theDialog	phx	_GetControlDItem	bcs noOldEditLine	pulllong <oldEditLineDeactivateOld		; 	movelong [<oldEditLine],0,<ControlPtr	pushlong [<ControlPtr],CtrlData	_LEDeactivate	bra ActivateNewnoOldEditLine		; 	plx	; pull useless result of GetControlDItem	plxActivateNew		; ;; First test if window is active or not. If not active, does not activate item;	pha	; space for window port	pha	_FrontWindow	pla	; compare front window to our dialog	plx	cmp <theDialog	bne SetEditID	cpx <theDialog+2	bne SetEditID	pushlongdp <hLE	_LEActivateSetEditID		; 	lda <itemID	; store the ID of the new active LE item	ldy #edittextID-wport	sta [<theDialog],yexit		; 	_SetPort	; port is on stack	lda #0quickexit		; 	ldx #SizeLocals	jmp quit10notFound		; 	plx	plx	bra quickexit	ENDP;______________________________________________________________________________;;        ParamText;;       input: param0:LONG - pointer to	string ^0 (zero=no change);              param1:LONG - pointer to	string ^1 (zero=no change);              param2:LONG - pointer to	string ^1 (zero=no change);              param3:LONG - pointer to	string ^1 (zero=no change);;      output: none;; Change History;; 4 March 88	STEVEN Glass;; Uses the incoming WAP instead of calling the control manager for the ; value of its direct page.;______________________________________________________________________________	ENTRY ParamTextParamText	PROCGlobals	equ 0SizeLocals	equ Globals+4	tay	; save the incoming WAP	tlink 16,SizeLocalsparamstart	equ input;; Get Dialog Manager Zero Page;	sty <Globals	stz <Globals+2	ldx #12	; start with param0	ldy #ParamString0NextParam		; 	lda <paramstart,x	bne ChangeIt	lda <paramstart+2,x	beq XYOffsets;; If param is not zero, change paramstring;ChangeIt		; 	lda <paramstart,x	sta [<Globals],y	iny	iny	lda <paramstart+2,x	sta [<Globals],y	iny	iny	bra XOffsetXYOffsets		; 	iny	iny	iny	inyXOffset		; 	dex	dex	dex	dex	bpl NextParam	; down to param3	lda #0	tunlink	rtl	ENDP;            copy  Modal.asm; Modal.asm		Jean-Charles Mourey	TITLE 'Modal Dialog Procedure';_____________________________________________________________________________;;        ModalDialog2;;       input: filterProc:LONG - procedure to be called repeatdly by ModalDialog;;      output: itemHitInfo:LONG - LoWord = ID of item Hit, HiWord = PartCode Hit;;    function: ModalDialog2 is an extension of ModalDialog.	In addition to;              returning the ID of the item Hit, it returns	as well the Part;              Code	Hit.;; Change History;; 4 March 88	STEVEN Glass;; Uses the incoming WAP instead of calling the control manager for the ; value of its direct page.;______________________________________________________________________________	ENTRY ModalDialog2ModalDialog2	PROCGlobals	equ 0SizeLocals	equ Globals+4	tay	; save incoming WAP	tlink 4,SizeLocalsfilterProc	equ inputitemHitInfo	equ output;; Clears result;	stz <itemHitInfo	stz <itemHitInfo+2;; Get Globals Page;	sty <Globals	stz <Globals+2;; Clears PartCode Hit in global page;	lda #0	ldy #PartCodeHit	sta [<Globals],y;; Call ModalDialog;	pha	; space for itemHit	pushlongdp <filterProc	_ModalDialog	bcs thiserror	pla	sta <itemHitInfo;; Get PartCode from	global page and store it in result;	ldy #PartCodeHit	lda [<Globals],y	sta <itemHitInfo+2;; exit, no error;	lda #0	; no error;; common exit;exit	ldx #SizeLocals	jmp quit4;; error;thiserror	plx	; get rid of result	bra exit	ENDP;_____________________________________________________________________________;;        ModalDialog;;       input: filterProc:LONG - procedure to be called repeatdly by ModalDialog;;      output: itemHit:WORD - ID of item Hit.;;    function: if the frontwindow is a modal dialog, ModalDialog repeatdly gets;              and handles events in the dialog's window; after handling an;              event involving an enabled dialog item, it returns with the item;              ID in itemHit.;;    filterProc: if	 is NULL, Standard Filter Called;                if	not NULL, filterProc called;	  then: if bit 31 of filterProc is set,	call Standard;	        Filter also.;; Change History;; 4 March 88	STEVEN Glass;; Uses the incoming WAP instead of calling the control manager for the ; value of its direct page.  Changed order of when Globals pointer was set; to do it while y-reg still valid.;; 5-Mar-91	Dave Lyons;; Defining bit 30 of the filter proc pointer = do I-Beam cursors.  See top of; file.;;______________________________________________________________________________	ENTRY ModalDialogModalDialog	PROCEvent	equ 0	;MUST BE ZERO! 17-Sep-90 DALWindow	equ Event+EVTSIZEDialog	equ Window+4Location	equ Dialog+4Control	equ Location+2ControlPtr	equ Control+4PartCode	equ ControlPtr+4Globals	equ PartCode+2PortSave	equ Globals+4SizeLocals	equ PortSave+4	tay	; save incoming WAP	tlink 4,SizeLocalsfilterProc	equ inputitemHit	equ output;; Get pointer to Globals Variables;	sty <Globals	stz <Globals+2;; For the moment, no item Hit;	stz <itemHit	stz <PartCode;; Zero out the I-Beam flag (5-Mar-91 DAL);	lda #0	ldy #IBeamFlag	sta [<Globals],y*** InitCursor on the way in was a bad idea (7-Mar-91 DAL)***;***; If we're doing IBeam cursors, call InitCursor (5-Mar-91 DAL)***;***	bit <filterProc+2***	bvc @noIBeam***	_InitCursor***@noIBeam;; Check that the front window is a modal dialog;	pha	; get dialog port	pha	_FrontWindow	lda 1,s	; get dialog port without pulling it	sta <Dialog	lda 3,s	sta <Dialog+2	pushword #Modal_Type ; dialog is still on stack	jsl WindowIsDialog	bcc DialogOk	lda #DLGERR+NotModalDialog	brl quickexitDialogOk	pha	; space for port pointer	pha	_GetPort	pulllong <PortSave	pushlongdp <Dialog	; set current port = the dialog	_SetPort	lda #0	pha	pha	_SetOriginEventLoop;; Call the Desk Manager procedure SystemTask; If the Desk Manager if not there, SystemTask will just return;	_SystemTask;; Blink the caret if there is an Edit Line item in the dialog;	pushlongdp <Dialog	jsl BlinkCaret;; Get next Event:;GetEvent		; 	pha	; space for boolean	result	pushword #$0FFF	; all events other than Application events***	pushzptr Event	; [optimized 17-Sep-90 DAL (Event must be 0)	pea 0	;  ...	phd	; ]	_GetNextEvent	pla	; if FALSE, event is null event;; See if there is a	user filter procedure to call;	lda <filterProc	bne UserFilter	lda <filterProc+1	beq StdFilterUserFilter		; 	pha	; space for filter result	pushlongdp <Dialog***	pushzptr Event	;optimized into following 2 lines 17-Sep-90 DAL	pea 0	phd	pushzptr itemHit	lda <filterProc	ldx <filterProc+1	jsl long_call	pla	; if TRUE, returns	bne exit;; If Bit 31 of filterProc is set, call StdFilter anyway;	lda <filterProc+2	and #$8000	beq DispEvent;; Call standard filter procedure;StdFilter		; 	pha	; space for filter result	pushlongdp <Dialog***	pushzptr Event	;optimized into following 2 lines 17-Sep-90 DAL	pea 0	phd	pushzptr itemHit	jsl StdFilterProc	pla	; if TRUE, returns	bne exit;; Dispatch Event;DispEvent	lda <Event+what	asl a	tax	lda >EventTable,x	pha	rtsEventTable	dc.w GotNullEvent-1		; inNull (5-Mar-91 DAL)***	DC.W EventLoop-1		; inNull	DC.W MouseDownEvent-1	; inButtDwn	DC.W EventLoop-1		; inButtUp	DC.W KeyDownEvent-1		; inKey	DC.W EventLoop-1	DC.W KeyDownEvent-1		; inAutoKey	DC.W UpdateEvent-1		; inUpdate	DC.W EventLoop-1	DC.W ActivateEvent-1	 ; inActWind	DC.W EventLoop-1		; inSwitch	DC.W EventLoop-1		; inAccess	DC.W EventLoop-1		; inDevice	DC.W EventLoop-1		; inApp1	DC.W EventLoop-1		; inApp2	DC.W EventLoop-1		; inApp3	DC.W EventLoop-1		; inApp4nextModalEvent	lda <itemHit	; if itemHit <> 0, returns	bne exit	brl EventLoopexit	pushlongdp <PortSave	_SetPort	; port is on stack;; Store PartCode Hit in Dialog Globals;	lda <PartCode	ldy #PartCodeHit	sta [<Globals],y	lda #0	; no errorquickexit	ldx #SizeLocals	jmp quit4;______________________________________________________________________________;; Null Event handler -- 5-Mar-91 DAL;; If bit 30 of the filter proc is on, then check what kind of item the cursor; is over, and set it to an Arrow or an I-Beam, as appropriate.;;______________________________________________________________________________noIbeams	brl NextModalEventGotNullEvent	bit <filterProc+2	bvc noIBeams; find the item the cursor is over	pea 0	tdc	adc #event+where	pha	_GlobalToLocal	pha	;space for FindCursorCtl	pushlong #theControlH	pei <event+where+2	pei <event+where	pha	pha	_FrontWindow	_FindCursorCtl	pla	;part code	beq @nonLineEdit	pha	pha	;space for GetCtlRefCon	pushlong >theControlH	_GetCtlRefCon	pla	;dItem number	pla	and #$7fff	;dialog item type	cmp #$0011	;Line Edit item?	bne @nonLineEdit@isLineEdit	ldy #IBeamFlag	lda [<globals],y	bne @cursorOkay	;already an I-Beam cursor	lda #1	sta [<globals],y	_IBeamCursor	bra @cursorOkay@nonLineEdit	ldy #IBeamFlag	lda [<globals],y	beq @cursorOkay	;already an arrow cursor	lda #0	sta [<globals],y	_InitCursor@cursorOkay	brl NextModalEventtheControlH	dc.l 0;______________________________________________________________________________;;        MouseDownEvent;______________________________________________________________________________MouseDownEvent;; Find window where	the mouse-down occurred and where in the window;	pha	; space for location	pushzptr Window	pushlongdp <Event+where	_FindWindow	pla	and #$7FFF	; get rid of InSysWindow bit	sta <Location;; If not in our dialog, beep;	lda <Window	cmp <Dialog	bne GotoBeep	lda <Window+2	cmp <Dialog+2	beq TestLocationGotoBeep	brl Beep;; if not in the content region, no item	hit -> exit;TestLocation	lda <Location	cmp #winContent	beq FindWhere	brl MDnoitem;; Find which item has been clicked in;FindWhere	pha	; space for partcode	pushzptr Control	pushlongdp <Event+where	pushlongdp <Dialog	_FindControl	pullword <PartCode	; if PartCode=0, no	item hit	bne CheckID	brl MDnoitem;; If ID is zero, does not handle item (non item controls);CheckID	movelong [<Control],0,<ControlPtr	ldy #iitemid	lda [<ControlPtr],y	bne CheckEditLine	brl MDnoitem;; If PartCode is inEditLine, call LEClick on the EditLine record;CheckEditLine	lda <PartCode	cmp #inEditLine	bne CheckNoTrack	pushzptr Event	pushlong [<ControlPtr],CtrlData ; hLE is in CtrlData field	_LEClick	brl EnableTest	; don't track an EditLine item;; If PartCode is inStatText or inUserItem, does not call TrackControl;CheckNoTrack	lda <PartCode	cmp #inStatText	beq NoTrack	cmp #inUserItem	beq NoTrack	cmp #inLongStatText	beq NoTrack	cmp #inLongStatText2 ; DAN H. (for LongStatText2)	beq NoTrack	; DAN H.	cmp #inIconItem	bne CheckScrollNoTrack	brl EnableTest;; If PartCode is in	up/down arrow or page up/down or thumb,	special track;CheckScroll	lda <PartCode	cmp #UP_PART	beq ScrollTrack	cmp #DOWN_PART	beq ScrollTrack	cmp #UPP_PART	beq ScrollTrack	cmp #DOWNP_PART	beq ScrollTrack	cmp #THUMB_PART	beq ScrollTrack;; Call TrackControl;StdTrack	pha	; space for partcode	pushlongdp <Event+where	lda #-1	; use control action procedure	pha	pha	pushlongdp <Control	_TrackControl	pullword <PartCode	; if PartCode=0, mouse released outside	beq MDnoitem	; of item, so no item hit.;; If an item has been hit, call EnableTest to see if should	return or not.;	brl EnableTest;; Call a special action procedure for scroll bar items;ScrollTrack	pha	; space for partcode	pushlongdp <Event+where	pushlong #scroll_action	pushlongdp <Control	_TrackControl	pullword <PartCode	beq MDnoitem	brl EnableTest;; Call the Sound Procedure with the sound number 1;Beep	pushword #1	ldy #AlertSoundProc+1 ; look if there is a custom sound	lda [<Globals],y	; (X = bits 8-23)	dey	; Y = AlertSoundProc	tax	bne CallCustomSound;;; Removed line 26-Jan-93 DAL;;;	dey	; test now low byte	lda [<Globals],y	bne CallCustomSound	sec	;24-Sep-90 DAL	jsl StdSoundProc	; call standard sound proc	bra MDexitCallCustomSound	lda [<Globals],y	; X already=bits 8-23, Y=AlertSoundProc	sec	;24-Sep-90 DAL	jsl long_call	; and A = low byte of procedure address	bra MDexitMDnoitem	stz <itemHit	stz <PartCodeMDexit	brl NextModalEvent;______________________________________________________________________________;;        KeyDownEvent;______________________________________________________________________________KeyDownEvent;; Check if there is	an active editLine item;	ldy #edittextID-wport	lda [<Dialog],y	bne editok	; if current edit item ID = 0, no item	brl KDnoitemeditok	tax;; If there is one, get the control handle to it.;	pha	; space for control	pha	pushlongdp <Dialog	phx	_GetControlDItem	Check_Error KDnotFound	pulllong <Control;; If the typed character is a tab character, change the active EditLine item;CheckTab	lda <Event+message	; char in lo order byte (check doc.)	and #$FF	;DAN H. FIX (changed from 7F)	cmp #9	; TAB = ASCII 9	bne CheckAppleKey;; Find next EditLine item in dialog;	pha	; space for result	pushlongdp <Dialog	pushlongdp <Control	jsl FindNextEditLine	plx;; Make it the new active EditLine item and select the line;	pushlongdp <Dialog	phx	pushword #0	pushword #32767	_SelIText	brl KDnoitem;; If Apple Key is down, does not pass the character to LineEdit (except arrows); but report that the item has been hit;CheckAppleKey	lda <Event+modif	and #$0100	; Test AppleKey modifier bit	beq CallLineEdit	lda <Event+message	; char in lo order byte (check doc.)	and #$FF	;DAN H. FIX (changed from 7f)	cmp #8	; left arrow	beq CallLineEdit	cmp #21	; right arrow	beq CallLineEdit	brl EnableTest;; Pass the typed character to Line Edit;CallLineEdit	movelong [<Control],0,<ControlPtr	lda <Event+message	; char in lo order byte (check doc.)	and #$FF	pha	pushworddp <Event+modif	pushlong [<ControlPtr],CtrlData ; LEHandle in CtrlData	_LEKey;; Item involved is an EditLine item, PartCode is inEditLine;	lda #inEditLine	sta <PartCode;; Call EnableTest to see if editText item is enabled or not.;	brl EnableTest;; Goes here if could not find current EditLine item;KDnotFound	plx	plxKDnoitem	stz <itemHit	stz <PartCodeKDexit	brl NextModalEvent;______________________________________________________________________________;;        UpdateEvent;; Note: The update event may or may not be for our window.  In case we're;       stuck attempting to handle somebody else's update events, we'll do;       the I-beam cursor polling during Update as well as Null events.;;______________________________________________________________________________UpdateEvent;; Redraws the dialog's content;	pushlongdp <Dialog	_BeginUpdate	pushlongdp <Dialog	_DrawDialog	pushlongdp <Dialog	_EndUpdate	stz <itemHit	stz <PartCode	brl GotNullEvent	;7-Mar-91 DAL***	brl NextModalEvent;_____________________________________________________________________________;;        ActivateEvent;______________________________________________________________________________ActivateEvent;; Activate the current EditLine item;	ldy #edittextID-wport	lda [<Dialog],y	beq Actexit	tax	pha	; space for control	pha	pushlongdp <Dialog	phx	_GetControlDItem	bcs ActNotFound	pulllong <Control	movelong [<Control],0,<ControlPtr	pushlong [<ControlPtr],CtrlData;; If dialog is now active, activate EditLine item, otherwise deactivate it;	lda <Event+modif	and #$0001	; get active flag	bne ActivateIt	_LEDeactivate	bra ActexitActivateIt		; 	_LEActivateActexit		; 	stz <itemHit	stz <PartCode	brl NextModalEvent;; Goes here if could not find current EditLine item;ActNotFound		; 	plx	plx	bra Actexit;______________________________________________________________________________;;        EnableTest;;       input: control handle to item hit is in the local "Control".;;      function: go	there if an item hit. Returns itemHit if item enabled.;                Returns 0 if item disabled.;______________________________________________________________________________EnableTest		; ;; If item hit, look	if item is enabled or not;	movelong [<Control],0,<ControlPtr	ldy #iitemtype	lda [<ControlPtr],y	and #ItemDisable	; if itemdisable, does not return	bne ETnoitem;; If item enabled, returns item ID;	moveword [<ControlPtr],iitemid,<itemHit	bra ETexitETnoitem		; 	stz <itemHit	stz <PartCodeETexit		; 	brl NextModalEvent	ENDP;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        WindowIsDialog;;       input: theDialog:LONG - pointer	to the (supposedly)	dialog port;              DialogType:WORD - type of dialog (Modal or Modeless);;      output: carry set if Window is not specified kind of	dialog;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY WindowIsDialogWindowIsDialog	PROCDialogHdl	equ 0SizeLocals	equ DialogHdl+4	link 6,SizeLocalsDialogType	equ inputtheDialog	equ DialogType+2	lday <theDialog	jsr dlg2handle	; try to convert dialog to handle	cmp #0	; if the handle doesnt exist, the front	bne frontisalloc	; window cant be a dialog	cpy #0	bne frontisalloc	lda #1	; make unlink set the carry	bra exitfrontisalloc		; 	pha	; get size of handle	pha	; (space for result)	pushay	_GetHandleSize	pullay	cmp #DLGSIZE	; if Handle Size is	not the size	bne notDialog	; of a dialog record, cant be a dialog	cpy #0	beq righthdlsizenotDialog		; 	lda #1	; make unlink set the carry	bra exitrighthdlsize		; 	ldy #dlgtype-wport	; if DialogRec->dlgtype = DialogType,	lda [<theDialog],y	; it is the correct	kind of dialog	cmp <DialogType	bne notDialog	lda #0	; make unlink clear	the carryexit		; 	unlink	rtl	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        BlinkCaret;;       input: theDialog:LONG - pointer	to the dialog port;;      output: none;;    function: Blink the caret if there	is an EditLine item	in theDialog;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY BlinkCaretBlinkCaret	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	link 4,SizeLocalstheDialog	equ input;; Call LEIdle on the current active Edit Line Item (if there is one);;	ldy #edittextID-wport	lda [<theDialog],y	beq exit	tax	pha	; space for control	pha	pushlongdp <theDialog	phx	_GetControlDItem	bcs notFound	pulllong <Control	movelong [<Control],0,<ControlPtr	pushlong [<ControlPtr],CtrlData	_LEIdle	; returns Line Edit	Error Statusexit		; 	unlink	rtlnotFound		; 	plx	plx	bra exit	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        StdFilterProc;;       input: theDialog:LONG - pointer	to the dialog port;              theEvent:LONG - pointer to the Event.;              itemHit:LONG - pointer to itemHit.;;      output: result:WORD - TRUE if must return.;;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY StdFilterProcStdFilterProc	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	link 12,SizeLocalsitemHit	equ inputtheEvent	equ itemHit+4theDialog	equ theEvent+4result	equ output;; Assume we won't want to bypass modaldialog;	stz <result;; Filters only KeyDown and AutoKey event;	ldy #what	lda [<theEvent],y	cmp #inKey	beq FilterIt	cmp #inAutoKey	beq FilterIt	brl exit;; Apple-X, Apple-C,	Apple-V handled as Cut/Copy/Paste;FilterIt	ldy #modif	lda [<theEvent],y	and #$0100	; Test AppleKey modifier bit	beq TestReturn	ldy #message	lda [<theEvent],y	and #$FF	;DAN H. FIX get character in lo byte	ora #'a'-'A'	; convert it to lower case	cmp #'x'	bne isCopy	pushlongdp <theDialog	_DlgCut	brl exitisCopy	cmp #'c'	bne isPaste	pushlongdp <theDialog	_DlgCopy	brl exitisPaste	cmp #'v'	bne TestReturn	pushlongdp <theDialog	_DlgPaste	brl exit;; Handles a Return as mouse down in default button;TestReturn	ldy #message	lda [<theEvent],y	and #$FF	;DAN H. FIX get character in lo byte	cmp #13	beq *+5	brl exit;; Get a handle to the default item;	pha	; space for control	pha	pushlongdp <theDialog	ldy #defbutID-wport	lda [<theDialog],y	pha	_GetControlDItem	Check_Error notFound	pulllong <Control;; Check that default item is a button;	movelong [<Control],0,<ControlPtr	ldy #iitemtype	lda [<ControlPtr],y	and #$7FFF	; get rid of item disable bit	cmp #ButtonItem	beq *+5	brl exit	; if not button, exit;; Check that the default button is visible and active;	ldy #CtrlFlag	lda [<ControlPtr],y	tax	and #CTRL_INVIS	; invisible?	bne exit	txa	and #C_HILITE	xba	; C_Hilite Flag is in high byte	cmp #255	; inactive?	beq exit;; Hilite the default button and unhilite it;	pushword #2	pushlongdp <Control	_HiliteControl	pushword #0	pushlongdp <Control	_HiliteControl;; Returns with itemHit = default button	if not disabled (shouldn't be);	movelong [<Control],0,<ControlPtr	ldy #iitemtype	lda [<ControlPtr],y	and #ItemDisable	; if itemdisable, does not return TRUE	bne exit;; If item enabled, returns item ID;	moveword [<theDialog],defbutID-wport,[<itemHit]	lda #1	; returns directly to application	sta <resultexit	unlink	rtlnotFound	plx	plx	bra exit	ENDP;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        StdSoundProc;;       input: SoundNum:WORD - number of the sound.;              Carry flag set if they clicked outside window (24-Sep-90 DAL);;      output: none.;;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY StdSoundProcStdSoundProc	PROC****	link 2****SoundNum	equ input**;**; Call the BEEP routine**;**CallBELL**	dec <SoundNum**	bmi exit****	_SysBeep****	bra CallBELL****exit**	lda #0**	unlink**	rtl*** Let's try this one more time, using bit 14 of SysBeep2 this time to delay*** the beeps until GetNextEvent gets called.  17-Feb-91 DAL	lda #$0004	;clicked outside dialog/alert	bcs @thisSound	lda 4,s	beq @stage0	ora #$4000	;stage 1..3: $4001..4003 (defer until GetNextEvent)	bra @thisSound@stage0	lda #$C000	;stage 0: no sound by default, defer until GNE@thisSound	pha	_SysBeep2	lda 2,s	sta 4,s	lda 1,s	sta 3,s	pla	rtl	ENDP;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        FindNextEditLine;;       input: theDialog:LONG - pointer	to dialog port;              PrevLEControl:LONG - control handle of previous EditLine item;;      output: NextLEID:WORD - ID of next EditLine item;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY FindNextEditLineFindNextEditLine	PROCControlPtr	equ 0SizeLocals	equ ControlPtr+4	link 8,SizeLocalsPrevLEControl	equ inputtheDialog	equ PrevLEControl+4NextLEID	equ output;; Get Next item in dialog;nextItem	movelong [PrevLEControl],0,<ControlPtr	movelong [<ControlPtr],CtrlNext,<PrevLEControl	lda <PrevLEControl	bne CheckEditLine	lda <PrevLEControl+2	beq RestartFromBeginning ; if end of list, go to beginning;; Check if this item is an EditLine item;CheckEditLine	movelong [PrevLEControl],0,<ControlPtr	ldy #iitemtype	lda [<ControlPtr],y	and #$7FFF	; get rid of item disable bit	cmp #EditLine	bne NextItem	; if not, next item	ldy #iitemid	lda [<ControlPtr],y	sta <NextLEID	lda #0	unlink	rtl;; If end of list reached, wraparound until we find (at least) the Prev EditLine;RestartFromBeginning	; get first item in dialog	movelong [<theDialog],wcontrol-wport,<PrevLEControl	bra CheckEditLine	ENDP;_____________________________________________________________________________;;        DefaultFilter;;       input: theDialog:LONG - pointer	to the dialog port;              theEvent:LONG - pointer to the Event.;              itemHit:LONG - pointer to itemHit.;;      output: result:WORD - TRUE if event filtered;_____________________________________________________________________________	ENTRY DefaultFilterDefaultFilter	PROC	tlink 12itemHit	equ inputtheEvent	equ itemHit+4theDialog	equ theEvent+4result	equ output	pushlongdp <theDialog	pushlongdp <theEvent	pushlongdp <itemHit	jsl StdFilterProc	pullword <result	lda #0	tunlink	rtl	ENDP;            copy  Modeless.asm; Modeless.asm		Jean-Charles Mourey	TITLE 'Modeless Dialog Routine';____________________________________________________________________________;;        IsDialogEvent;;       input: theEvent:LONG - pointer to the Event Record;;      output: result:WORD - TRUE if it	is a dialog event;;_____________________________________________________________________________	ENTRY IsDialogEventIsDialogEvent	PROCWindow	equ 0	;MUST BE ZERO 17-Sep-90 DALDialog	equ Window+4SizeLocals	equ Dialog+4	tlink 4,SizeLocalstheEvent	equ inputresult	equ output;; Initialize result	to FALSE;	stz <result;; Test if front window is a modeless dialog;	pha	; space for window pointer	pha	_FrontWindow	lda 1,s	; get dialog pointer without pulling it	sta <Dialog	lda 3,s	sta <Dialog+2	pushword #Modeless_Type ; dialog is still on stack	jsl WindowIsDialog	bcs FrontNotModeless;; Is it a mouse down event in the content region of the active dialog;	ldy #what	lda [<theEvent],y	cmp #9	; is it a switch event or higher?	bcs bnoerror	; don't claim them	cmp #inActWind	beq TestForDialog	cmp #inUpdate	beq TestForDialog	cmp #inButtDwn	; if other than mouse down, it is	bne ReturnTrue;; Find window and location in window of	mouse down event;	pha	; space for location***	pushzptr Window	;optimized into following 2 lines 17-Sep-90 DAL	pea 0	phd	pushlong [<theEvent],where	_FindWindow	pla	and #$7FFF	; get rid of InSysWindow bit	tax	; X contains location;; If not in our dialog, not dialog event;	lda <Window	cmp <Dialog	bne noerror	lda <Window+2	cmp <Dialog+2	bne noerror;; Test that location is in the content region;	cpx #winContent	; only return true of wincontent, HY 7/13/88	bne noerror	; if not mouse down in content		; of modeless dialog then handle		; taskmaster event as normal		 returnTRUE	lda #1	sta <resultbnoerror	bra noerror;; If front window is not a modeless dialog, is it an activate/update event in; a dialog ?;FrontNotModeless	ldy #what	lda [<theEvent],y	cmp #inActWind	beq TestForDialog	cmp #inUpdate	bne noerror	; not activate nor update, so exitTestForDialog	pushlong [<theEvent],message	pushword #Modeless_Type ; DAN H. (changed from Modeless_type)	jsl WindowIsDialog	bcc returnTRUE	; DAN H. (branch if	modal or modeless)	pushlong [<theEvent],message	pushword #Modal_Type ; DAN H. (changed from Modeless_type)	jsl WindowIsDialog	bcc returnTRUE	; DAN H. (branch if	modal or modeless)noerror	lda #0exit	ldx #SizeLocals	jmp quit4	ENDP;_____________________________________________________________________________;;        DialogSelect;;       input: theEvent:LONG - pointer to the Event Record;              theDialogPtr:LONG - pointer to the dialog pointer;              itemHitPtr:LONG - pointer to the itemHit;;      output: result:WORD - TRUE if event handled by DialogSelect;______________________________________________________________________________	ENTRY DialogSelectDialogSelect	PROCDialog	equ 0FrontModeless	equ Dialog+4Control	equ FrontModeless+2ControlPtr	equ Control+4PartCode	equ ControlPtr+4PortSave	equ PartCode+2SizeLocals	equ PortSave+4	tlink 12,SizeLocalsitemHitPtr	equ inputtheDialogPtr	equ itemHitPtr+4theEvent	equ theDialogPtr+4result	equ output;; Initialize ouputs	and flag to zero;	lda #0	sta <result	sta [<itemHitPtr]	sta <FrontModeless;; Get the current port;	pha	; space for port pointer	pha	_GetPort	pulllong <PortSave;; Blink the caret on the front window if it is a modeless dialog;	pha	; space for window pointer	pha	_FrontWindow	lda 1,s	; get dialog pointer without pulling it	sta <Dialog	sta [<theDialogPtr]	lda 3,s	sta <Dialog+2	ldy #2	sta [<theDialogPtr],y	pushword #Modeless_Type ; dialog is still on stack	jsl WindowIsDialog	bcs DispEvent	lda #1	; set FrontModeless	flag to TRUE	sta <FrontModeless	pushlongdp <Dialog	; set current port = the dialog	_SetPort	; only if it is the	front window	lda #0	pha	pha	_SetOrigin	pushlongdp <Dialog	jsl BlinkCaret;; Call standard filter;	pha	; space for filter result	pushlongdp <Dialog	pushlongdp <theEvent	pushlongdp <itemHitPtr	jsl StdFilterProc	pla	beq DispEvent	sta <result	bra exit;; Dispatch Event;DispEvent	ldy #what	lda [<theEvent],y	asl a	tax	lda >EventTable,x	pha	rtsEventTable	DC.W exit-1		; inNull	DC.W MouseDownEvent-1 	; inButtDwn	DC.W exit-1		; inButtUp	DC.W KeyDownEvent-1		; inKey	DC.W exit-1	DC.W KeyDownEvent-1		; inAutoKey	DC.W UpdateEvent-1		; inUpdate	DC.W exit-1	DC.W ActivateEvent-1 	; inActWind	DC.W exit-1		; inSwitch	DC.W exit-1		; inAccess	DC.W exit-1		; inDevice	DC.W exit-1		; inApp1	DC.W exit-1		; inApp2	DC.W exit-1		; inApp3	DC.W exit-1		; inApp4exit	pushlongdp <PortSave	_SetPort	lda #0	tunlink	rtl;____________________________________________________________________________;;        MouseDownEvent;_____________________________________________________________________________MouseDownEvent;; If front window is not a modeless dialog, exit;	lda <FrontModeless	beq exit;; Find window where	the mouse-down occurred and where in the window;	pha	; space for location	pushlongdp <theDialogPtr	pushlong [<theEvent],where	_FindWindow	pla	and #$7FFF	; get rid of InSysWindow bit	tax	; location in X;; If not in front dialog, exit;	lda [<theDialogPtr]	cmp <Dialog	bne exit	ldy #2	lda [<theDialogPtr],y	cmp <Dialog+2	bne exit;; If not in the content region, no item	hit -> exit;	cpx #winContent	beq FindWhere	brl exit;; Find which item has been clicked in;FindWhere		; 	pha	; space for partcode	pushzptr Control	pushlong [<theEvent],where	pushlongdp <Dialog	_FindControl	pullword <PartCode	; if partcode=0, no	item hit	bne CheckID	brl exit;; If ID is 0, does not handle item (non	item controls);CheckID	movelong [<Control],0,<ControlPtr	ldy #iitemid	lda [<ControlPtr],y	bne CheckEditLine	brl exit;; If PartCode is in	EditLine, call LEClick on the EditLine record;CheckEditLine	lda <PartCode	cmp #inEditLine	bne CheckNoTrack	pushlongdp <theEvent	pushlong [<ControlPtr],CtrlData ; hLE is in CtrlData field	_LEClick	brl EnableTest;; If PartCode is inStatText, inUserItem, inLongStatText,; or inIconItem, does not TrackControl;CheckNoTrack	lda <PartCode	cmp #inStatText	beq NoTrack	cmp #inUserItem	beq NoTrack	cmp #inLongStatText	beq NoTrack	cmp #inLongStatText2 ; DAN H. (added for LongStatText2)	beq NoTrack	; DAN H.	cmp #inIconItem	bne CheckScrollNoTrack	brl EnableTest;; If PartCode is in	up/down arrow or page up/down or thumb,	special track;CheckScroll	lda <PartCode	cmp #UP_PART	beq ScrollTrack	cmp #DOWN_PART	beq ScrollTrack	cmp #UPP_PART	beq ScrollTrack	cmp #DOWNP_PART	beq ScrollTrack	cmp #THUMB_PART	beq ScrollTrack;; Call TrackControl;StdTrack		; 	pha	; space for partcode	pushlong [<theEvent],where	lda #-1	; use control action procedure	pha	pha	pushlongdp <Control	_TrackControl	pullword <PartCode	; if PartCode=0, mouse released outside	beq MDnoitem	; of item, so no item hit.;; If an item has been hit, call EnableTest to see if should	return or not.;	brl EnableTest;; Call a special action procedure for scroll bar items;ScrollTrack		; 	pha	; space for partcode	pushlong [<theEvent],where	pushlong #scroll_action	pushlongdp <Control	_TrackControl	pullword <PartCode	beq MDnoitem	brl EnableTestMDnoitem	brl exit;______________________________________________________________________________;;        KeyDownEvent;______________________________________________________________________________KeyDownEvent;; If front window is not a modeless dialog, exit;	lda <FrontModeless	bne LookForEditLine	brl KDnoitem;; Check if there is	an active editLine item;LookForEditLine	ldy #edittextID-wport	lda [<Dialog],y	bne editok	; if current edit item ID = 0, no item	brl KDnoitemeditok	tax;; If there is one, get the control handle to it.;	pha	; space for control	pha	pushlongdp <Dialog	phx	_GetControlDItem	pulllong <Control;; If the item has not been found, exit no item;	lda <Control	bne CheckTab	lda <Control+2	bne CheckTab	brl KDnoitem;; If the typed character is a tab character, change the active EditLine item;CheckTab	ldy #message	lda [<theEvent],y	; char in lo order byte (check doc.)	and #$FF	cmp #9	; TAB = ASCII 9	bne CheckAppleKey;; Find next EditLine item in dialog;	pha	; space for result	pushlongdp <Dialog	pushlongdp <Control	jsl FindNextEditLine	plx;; Make it the new active EditLine item and select the line;	pushlongdp <Dialog	phx	pushword #0	pushword #32767	_SelIText	brl KDnoitem;; If Apple Key is down, does not pass the character to LineEdit;CheckAppleKey	ldy #modif	lda [<theEvent],y	and #$0100	; Test AppleKey modifier bit	beq CallLineEdit	ldy #message	lda [<theEvent]	; char in lo order byte (check doc.)	and #$7F	cmp #8	; left arrow	beq CallLineEdit	cmp #21	; right arrow	beq CallLineEdit	brl KDnoitem;; Pass the typed character to Line Edit;CallLineEdit	movelong [<Control],0,<ControlPtr	ldy #message	lda [<theEvent],y	; char in lo order byte (check doc.)	and #$FF	pha	ldy #modif	lda [<theEvent],y	pha	pushlong [<ControlPtr],CtrlData ; LEHandle in CtrlData	_LEKey;; Call EnableTest to see if EditLine item is enabled or not.;	brl EnableTestKDnoitem	brl exit;______________________________________________________________________________;;        UpdateEvent;______________________________________________________________________________UpdateEvent;; Get dialog port;	jsr getdlgport	movelong [<theDialogPtr],0,<Dialog;; Redraws the dialog's content;	pushlongdp <Dialog	_BeginUpdate	pushlongdp <Dialog	_DrawDialog	pushlongdp <Dialog	_EndUpdate	brl exit;______________________________________________________________________________;;        ActivateEvent;______________________________________________________________________________ActivateEvent;; Get dialog port;	jsr getdlgport	movelong [<theDialogPtr],0,<Dialog;; Look if there is any EditLine item;	ldy #edittextID-wport	lda [<Dialog],y	bne ACeditok	; if current edit item ID = 0, no item	brl exitACeditok	tax;; If there is one, get the control handle to it.;	pha	; space for control	pha	pushlongdp <Dialog	phx	_GetControlDItem	bcs ActNotFound	pulllong <Control	movelong [<Control],0,<ControlPtr	pushlong [<ControlPtr],CtrlData;; If dialog is now active, activate EditLine item, otherwise deactivate it;	ldy #modif	lda [<theEvent],y	and #$0001	; get active flag	bne ActivateIt	_LEDeactivate	bra ActexitActivateIt	_LEActivateActexit	brl exit;; Goes here if could not find current EditLine item;ActNotFound	plx	plx	bra Actexit;++++++++++++++++++++++++++++++++++++++++++++++++++++;;        Get the dialog port from the Event Record;;+++++++++++++++++++++++++++++++++++++++++++++++++++++getdlgport	plx	; get rts	ldy #message	lda [<theEvent],y	sta [<theDialogPtr]	iny	iny	lda [<theEvent],y	ldy #2	sta [<theDialogPtr],y	phx	; set rts	rts;______________________________________________________________________________;;        EnableTest;;       input: control handle to item hit is in the local "Control".;;      function: go	there if an item hit. Returns itemHit if item enabled.;                Returns 0 if item disabled.;______________________________________________________________________________EnableTest;; If item hit, look	if item is enabled or not;	movelong [<Control],0,<ControlPtr	ldy #iitemtype	lda [<ControlPtr],y	and #ItemDisable	; if itemdisable, does not return	bne ETnoitem;; If item enabled, returns item ID;	ldy #iitemid	lda [<ControlPtr],y	sta [<itemHitPtr]	lda #1	sta <resultETnoitem	brl exit	ENDP;            copy  DDraw.asm; DDraw.asm		Jean-Charles Mourey	TITLE 'DrawDialog Routine';_____________________________________________________________________________;;        DrawDialog;;       input: theDialog:LONG - pointer	to the dialog.;;      output: none.;;    function: draws the contents of the given dialog box.;______________________________________________________________________________	ENTRY DrawDialogDrawDialog	PROC	tlink 4;; Since all the items in a dialog are controls (standard or	custom),; just call DrawControls for all controls in the dialog.;	pushlongdp <input	_DrawControls	; return DrawControls Error Status	ldx #0	jmp quit4	ENDP;____________________________________________________________________________;;        UpdateDialog;;       input: theDialog:LONG - pointer	to the dialog port;              UpdateRgn:LONG - handle to region of dialog to update;;      output: none;_____________________________________________________________________________	ENTRY UpdateDialogUpdateDialog	PROCPortSave	equ 0ClipSave	equ PortSave+4SizeLocals	equ ClipSave+4	tlink 8,SizeLocalsUpdateRgn	equ inputtheDialog	equ UpdateRgn+4	pha	; save previous port	pha	; (space for port pointer)	_GetPort	pulllong <PortSave	pushlongdp <theDialog	; set port = dialog	port	_SetPort	pha	; save previous clip region	pha	; (space for clip region)	_NewRgn	pulllong <ClipSave	pushlongdp <ClipSave	_GetClip	pushlongdp <UpdateRgn	; set clip region =	update region	_SetClip	pushlongdp <theDialog	; draw dialog	_DrawDialog	bcc noerror	pha	; save DrawDialog Error Status	bra RestoreEverythingnoerror		;	        ; if no error, error status = 0	lda #0	phaRestoreEverything		; 	pushlongdp <ClipSave	; restore previous clip region	_SetClip	pushlongdp <ClipSave	; dispose of save region	_DisposeRgn	pushlongdp <PortSave	; restore previous port	_SetPort	pla	; restore DrawDialog Error Status	ldx #SizeLocals	jmp quit8	; fixedby SEG on 19	Dec 86	ENDP;            copy  DData.asm; DData.asm		Jean-Charles Mourey	TITLE 'Dialog Manager Datas';            copy  DScrap.asm; DScrap.asm		Jean-Charles Mourey	TITLE 'Cut/Copy/Paste Dialog Procedures';____________________________________________________________________________;;        DlgCut;;       input: theDialog:LONG - pointer	to the dialog port.;;      output: none.;;    function: if there is a current edittext item, apply the cut operation;              to it.;____________________________________________________________________________	ENTRY DlgCutDlgCut	PROC	ldx #cutcmd	bra DlgScrap	ENDP;____________________________________________________________________________;;        DlgCopy;;       input: theDialog:LONG - pointer	to the dialog port.;;      output: none.;;    function: if there is a current edittext item, apply the copy operation;              to it.;____________________________________________________________________________	ENTRY DlgCopyDlgCopy	PROC	ldx #copycmd	bra DlgScrap	ENDP;____________________________________________________________________________;;        DlgPaste;;       input: theDialog:LONG - pointer	to the dialog port.;;      output: none.;;    function: if there is a current edittext item, apply the paste operation;              to it.;____________________________________________________________________________	ENTRY DlgPasteDlgPaste	PROC	ldx #pastecmd	bra DlgScrap	ENDP;____________________________________________________________________________;;        DlgDelete;;       input: theDialog:LONG - pointer	to the dialog port.;;      output: none.;;    function: if there is a current edittext item, apply the delete operation;              to it.;____________________________________________________________________________	ENTRY DlgDeleteDlgDelete	PROC	ldx #deletecmd	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        DlgScrap;;       input: theDialog:LONG - pointer	to the dialog port.;              Y register = scrap command (cut,copy,paste or delete);;      output: none.;;    function: if there is a current edittext item, apply the scap operation;              to it.;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY DlgScrapDlgScrap	PROCControl	equ 0ControlPtr	equ Control+4SizeLocals	equ ControlPtr+4	tlink 4,SizeLocalstheDialog	equ input	phx	; save scrap command	ldy #edittextID-wport	lda [<theDialog],y	bne GetIt	plx	; pull scrap command	lda #DLGERR+ItemNotFound ; if no current EditLine item, error	bra exitGetIt	tax;; Get handle to current edit text's control;	pha	; space for control	pha	pushlongdp <theDialog	phx	_GetControlDItem	bcs notFound	pulllong <Control	movelong [<Control],0,<ControlPtr	plx	; get scrap command	pushlong [<ControlPtr],CtrlData ; CtrlData = hLE;================================================================;;  Here, I compute directly the call number with scrapcmd,;  assuming the call numbers for LECut,	LECopy, LEPaste and;  LEDelete won't change.;;        LECut    =	20+256*18;        LECopy   =	20+256*19;        LEPaste  =	20+256*20;        LEDelete =	20+256*21;;================================================================	txa	; add base number to scrap command	clc	adc #18+20*256	; (Acc should be switched lo-hi)	xba	; and switch it	tax	jsl $E10000	; return LineEdit Error Statusexit	ldx #SizeLocals	jmp quit4notFound		; 	plx	; pull useless control	plx	plx	; pull scrap command	bra exit	ENDP;            copy  DUtils.asm; DUtils.asm		Jean-Charles Mourey	TITLE 'Dialog Manager Internal Utilities';++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        dlg2handle;;       input: theDialog:LONG in AY - pointer to the dialog	port.;;      output: DialogHandle:LONG in AY - handle to the dialog record.;;    function: given a pointer to the dialog port, retrieves the;              handle to the dialog record.;;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY dlg2handledlg2handle	PROC;; Find beginning of	dialog record;	sec	sbc #wport	bcs findit	deyfindit	pushlong #0	pushay	; Location of Handle	_FindHandle	pullay	rts	ENDP;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        long_call;;       input: X = bits 8-23 of address	of destination routine;              A = bits 0-15 of address	of destination routine;                  (only bits 0-8 are used);;      output: calling this routine is the same as:;;                 jsl (ax);;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY long_calllong_call	PROC		; HY 8/4/88, old code decremented data bank	phx	; push middle+high byte of address	phb	; push extra byte on stack		dec a	; decrement a so low word looks like a 		; return address	sta 1,s	; overstore low word		rtl	; go to routine	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        quit0;;       input: A=error code;;      output: none;;    function: exit	from a procedure with no input and adjust carry;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY quit0quit0	PROC;; Stack is: output,	rtl1, rtl2, local space, previous D register;	jsr disposelocals;; Stack is: output,	rtl1, rtl2;	tya	; adjust carry	cmp #1	rtl	; quit procedure	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        quit2;;       input: A=error code;;      output: none;;    function: exit	from a procedure with 2 bytes of input and adjust carry;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY quit2quit2	PROC Export;; Stack is: output,	input, rtl1, rtl2, local space, previous D register;	jsr disposelocals;; Stack is: output,	input, rtl1, rtl2;;; Remove input parameters;	lda 5,s	sta 7,s	lda 3,s	sta 5,s	lda 1,s	sta 3,s	pla	; add 2 to stack pointer	tya	; adjust carry	cmp #1	rtl	; quit procedure	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        quit4;;       input: A=error code;;      output: none;;    function: exit	from a procedure with 4 bytes of input and adjust carry;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY quit4quit4	PROC	jsr disposelocals;; Remove input parameters;	lda 5,s	sta 9,s	lda 3,s	sta 7,s	lda 1,s	sta 5,s	pla	; add 4 to stack pointer	pla	tya	; adjust carry	cmp #1	rtl	; quit procedure	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        quit6;;       input: A=error code;;      output: none;;    function: exit	from a procedure with 6 bytes of input and adjust carry;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY quit6quit6	PROC	jsr disposelocals;; Remove input parameters;	lda 5,s	sta 11,s	lda 3,s	sta 9,s	lda 1,s	sta 7,s	pla	; add 6 to stack pointer	pla	pla	tya	; adjust carry	cmp #1	rtl	; quit procedure	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        quit8;;       input: A=error code;;      output: none;;    function: exit	from a procedure with 8 bytes of input and adjust carry;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY quit8quit8	PROC	jsr disposelocals;; Remove input parameters;	lda 5,s	sta 13,s	lda 3,s	sta 11,s	lda 1,s	sta 9,s	pla	; add 8 to stack pointer	pla	pla	pla	tya	; adjust carry	cmp #1	rtl	; quit procedure	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        quit10;;       input: A=error code;;      output: none;;    function: exit	from a procedure with 10 bytes of input	and adjust carry;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY quit10quit10	PROC	jsr disposelocals;; Remove input parameters;	lda 5,s	sta 15,s	lda 3,s	sta 13,s	lda 1,s	sta 11,s	pla	; add 10 to stack pointer	pla	pla	pla	pla	tya	; adjust carry	cmp #1	rtl	; quit procedure	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        quitdefproc;;       input: A=error code;;      output: none;;    function: exit	from a defproc with	10 bytes of input and adjust carry;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY quitdefprocquitdefproc	PROC	jsr disposelocals;; Remove input parameters;	lda 2,s	sta 12,s	lda 1,s	sta 11,s	pla	; add 10 to stack pointer	pla	pla	pla	pla	tya	; adjust carry	cmp #1	rtl	; quit procedure	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        disposelocals;;       input: X=size of local space;;      output: none;;    function: restore zero page, save error code, and remove local vars from;              stack.;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY disposelocalsdisposelocals	PROC	tay	; save error code	pla	; save return address	pld	; restore zero page	cpx #0	beq exit;; Remove local vars	from stack;nextbyte		; 	sta 1,s	; store return address on stack	pla	; decrement stack and get return address	dex	; (that's a huge trick!)	dex	bne nextbyteexit		; 	pha	; restore return address	rts	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        storeLONGinZP;;       input: LongValue:LONG - value to store in the zero page;              Y register = offset in zero page where to put the value;              A-reg = value of WAP;;      output: none;;; Change History;; 4 March 88	STEVEN Glass;; Uses the incoming WAP instead of calling the control manager for the ; value of its direct page.;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY storeLONGinZPstoreLONGinZP	PROCGlobals	equ 0SizeLocals	equ Globals+4	tax	; save WAP 	tlink 4,SizeLocals	phy	; save zero page offset	stx <Globals	stz <Globals+2	ply	; restore zero page	offset;; Store the LONG input parameter in the	Zero Page at the specified position;	lda <input	sta [<Globals],y	iny	; Added 28 Jan 87	iny	; oops--forgot the second word of	lda <input+2	; the long	sta [<Globals],y	lda #0	ldx #SizeLocals	jmp quit4	ENDP;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        getWORDfromZP;;       input: Y register = offset in zero page where is the value;;      output: WordValue:WORD - value read from zero page;; Change History;; 4 March 88	STEVEN Glass;; Uses the incoming WAP instead of calling the control manager for the ; value of its direct page.;;++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY getWORDfromZPgetWORDfromZP	PROCGlobals	equ 0SizeLocals	equ Globals+4	tax	; save wap value	tlink 0,SizeLocals	phy	; save zero page offset	stx <Globals	stz <Globals+2	ply	; restore zero page	offset;; Store the asked value in the output;	lda [<Globals],y	sta <output	lda #0	ldx #SizeLocals	jmp quit0	ENDP	TITLE 'StatText Items Definition Procedure';___________________________________________________________________________;;       StatTextDefProc;;       input: message:WORD - desired operation;              param:LONG - depends on operation;              theControl:LONG - handle	to control;;      output: RetValue:LONG - depends on operation;; Change History;; 07 Oct 88	Steven Glass;; Only deref the control handle if the message is not recsize.;____________________________________________________________________________	ENTRY StatTextDefProcStatTextDefProc	PROCControlPtr	equ 0Rect	equ ControlPtr+4TextPtr	equ Rect+8TextLen	equ TextPtr+4SizeLocals	equ TextLen+2	nop	link 10,SizeLocalstheControl	equ inputparam	equ theControl+4CtlMessage	equ param+4RetValue	equ output;; Zeroes out RetValue;	stz <RetValue	stz <RetValue+2	lda <ctlMessage	cmp #recsize	beq SkipThisStuff;; Get Pointer to control and copy display rectangle;	movelong [<theControl],0,<ControlPtr	movelong [<ControlPtr],CtrlRect,<Rect	movelong [<ControlPtr],CtrlRect+4,<Rect+4SkipThisStuff	lda <CtlMessage	asl a	tax	lda >CmdTable,x	pha	rtsCmdTable	DC.W DrawStatText-1	DC.W StatTextExit-1	DC.W TestStatText-1	DC.W StatTextExit-1	DC.W StatTextExit-1	DC.W StatTextExit-1	DC.W StatTextExit-1	DC.W StatTextExit-1	DC.W StatTextExit-1	DC.W DrawStatText-1	; new value fall thru draw routine	DC.W StatTextExit-1	DC.W StatTextExit-1	DC.W RecStatText-1StatTextExit	ldx #SizeLocals	jmp quitdefproc********************* Draw StatText*******************DrawStatText;; Call TextBox to draw the static text;	jsr NormalTextColor;; Using TextPtr, creates a new string where the ^n are replaced by the ParamStr;	movelong [<ControlPtr],CtrlData,<TextPtr	lda [<TextPtr]	; get text length	and #$FF	sta <TextLen;; If string is empty, exit;	beq exit	add4 <TextPtr,#1,<TextPtr ; get pointer	to beginning of text	pha	; space for new text pointer	pha	pha	; space for new text length	pushlongdp <TextPtr	pushworddp <TextLen	jsl InsertParamString	pullword <TextLen	; new text length	pulllong <TextPtr	; new text pointer (dereferenced hdl)	pushlongdp <TextPtr	pushworddp <TextLen	pushzptr <Rect	pushword #0	; Left justification	_LETextBox;; Dispose of pointer (actually handle for the created string);	pha	; space for handle	pha	pushlongdp <TextPtr	_FindHandle	_DisposeHandleexit	brl StatTextExit********************* Test StatText*******************TestStatText	movelong #inStatText,<RetValue	brl StatTextExit********************* RecSize StatText*******************RecStatText;; Returns StatTextSIZE;	movelong #StatTextSIZE,<RetValue	brl StatTextExit	ENDP;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;        InsertParamString;;       input: SourceText:LONG - pointer to text string;              SourceLen:WORD - length of text string;;      output: DestText:LONG - pointer to text with the paramstrings;              DestLen:WORD - length of	dest string;;    function: replaces the ^0 to ^3 by	the corresponding paramstrings (set by;              ParamText).;;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY InsertParamStringInsertParamString	PROCGlobals	equ 0StringHandle	equ Globals+4SourceOffset	equ StringHandle+4DestOffset	equ SourceOffset+2ParmText	equ DestOffset+2ParmLen	equ ParmText+4DestLenBase	equ ParmLen+2SizeLocals	equ DestLenBase+2	link 6,SizeLocalsSourceLen	equ inputSourceText	equ SourceLen+2DestLen	equ outputDestText	equ DestLen+2;; Get Dialog Manager Zero Page;	pha	_GetCtlDPage	pla	sta <Globals	stz <Globals+2;; Create a handle for the new text;	pha	; space for handle	pha	pushlong #520	; 520 characters (limit effects)	ldy #mmgrID	; Memory Manager ID	lda [<Globals],y	pha	pushword #Attr_NoCross	pha	; no location	pha	_NewHandle	Check_Error NotAllocated	lda 1,s	; get string handle	without pulling it	sta <StringHandle	lda 3,s	sta <StringHandle+2	_HLock	; StringHandle is on stack	movelong [<StringHandle],0,<DestText	stz <SourceOffset	stz <DestLen	stz <DestLenBaseNextSourceChar	ldy <SourceOffset	lda [<SourceText],y	tax	and #$7F	cmp #'^'	beq CheckNeedParam	txaDirectCopyChar	ldy <DestLen	sta [<DestText],y	inc <SourceOffset	lda <SourceOffset	cmp <SourceLen	blt IncDestLen	brl CopyDestLengthIncDestLen	inc <DestLen	lda <DestLen	sec	sbc <DestLenBase	cmp #256	blt NextSourceChar;; If more chars needed, expand string by 256 chars;	pushlongdp <StringHandle	_HUnlock	lda #0	pha	; space for handle size	pha	pushlongdp <StringHandle	_GetHandleSize	lda 1,s	; HdlSize is on stack	clc	; Add 256 to it	adc #256	; and re-store it on the stack	sta 1,s	lda 3,s	adc #0	sta 3,s	pushlongdp <StringHandle	_SetHandleSize	pushlongdp <StringHandle	_HLock	movelong [<StringHandle],0,<DestText	lda <DestLenBase	clc	adc #256	sta <DestLenBase	brl NextSourceCharCheckNeedParam	iny	cpy <SourceLen	beq DirectCopyChar	lda [<SourceText],y	and #$7F	sec	sbc #'0'	bmi NotParamString	cmp #4	blt IsParamStringNotParamString	dey	lda [<SourceText],y	brl DirectCopyChar;; Insert Param String;IsParamString;; Get Pointer to ParmString;	asl a	; calculate offset to ParamString	asl a	; in Dialog Manager	zero page	clc	adc #ParamString0	tay	lda [<Globals],y	sta <ParmText	iny	iny	lda [<Globals],y	sta <ParmText+2	lda [<ParmText]	and #$FF	beq SkipExpChar	; if the string is zero then just skip it, HY 7/26/88	sta <ParmLen	ldx #1NextParmChar	txy	lda [<ParmText],y	ldy <DestLen	sta [<DestText],y	inx	; next 2 char.	inx	inc <DestLen	inc <DestLen	cpx <ParmLen	blt NextParmChar	beq NextParmChar;; if previous x was	exactly ParmLen, then we copied 1 char more than ParmLen;	dex	dex	cpx <ParmLen	bne SkipExpChar	dec <DestLen	; we incremented too much;; Skip the two ^n characters, check if end of source text, continue if not;SkipExpChar		; 	inc <SourceOffset	; skip ^	inc <SourceOffset	; next char	lda <SourceOffset	cmp <SourceLen	bge exit	; if n is last char, then we're done. 		; changed bge CopyDestLength to bge Exit, because if		; ^n was at end of line then the DestLen would be		; incremented by one too many. HY 5/9/88	brl NextSourceCharCopyDestLength		; 	inc <DestLen	; length is maxoffset+1exit		; 	unlink	rtlNotAllocated		; 	tax	; save MMgr error code	pla	; pull useless result	pla	movelong <SourceText,<DestText ; and pass original string as result	moveword <SourceLen,<DestLen	txa	bra exit	ENDP;___________________________________________________________________________;;       LongStatTextDefProc;;       input: message:WORD - desired operation;              param:LONG - depends on operation;              theControl:LONG - handle	to control;;      output: RetValue:LONG - depends on operation;; Change History;; 07 Oct 88	Steven Glass;; Only deref the control handle if the message is not recsize.;____________________________________________________________________________	ENTRY LongStatTextDefProcLongStatTextDefProc	PROCControlPtr	equ 0Rect	equ ControlPtr+4TextPtr	equ Rect+8TextLen	equ TextPtr+4SizeLocals	equ TextLen+2	nop	link 10,SizeLocalstheControl	equ inputparam	equ theControl+4CtlMessage	equ param+4RetValue	equ output;; Zeroes out RetValue;	stz <RetValue	stz <RetValue+2	lda <ctlMessage	cmp #recSize	beq SkipThis;; Get Pointer to control and copy display rectangle;	movelong [<theControl],0,<ControlPtr	movelong [<ControlPtr],CtrlRect,<Rect	movelong [<ControlPtr],CtrlRect+4,<Rect+4SkipThis	lda <CtlMessage	asl a	tax	lda >CmdTable,x	pha	rtsCmdTable	DC.W DrawLongStatText-1	DC.W LongStatTextExit-1	DC.W TestLongStatText-1	DC.W LongStatTextExit-1	DC.W LongStatTextExit-1	DC.W LongStatTextExit-1	DC.W LongStatTextExit-1	DC.W LongStatTextExit-1	DC.W LongStatTextExit-1	DC.W DrawLongStatText-1 ; new value fall thru draw routine	DC.W LongStatTextExit-1	DC.W LongStatTextExit-1	DC.W RecLongStatText-1LongStatTextExit	ldx #SizeLocals	jmp quitdefproc********************* Draw LongStatText*******************DrawLongStatText;; Call TextBox to draw the static text;	jsr NormalTextColor;; Using TextPtr, creates a new string where the ^n are replaced by the ParamStr;	ldy #CtrlValue	lda [<ControlPtr],y	sta <TextLen;; If empty string, exit;	beq exit	pha	; space for new text pointer	pha	pha	; space for new text length	pushlong [<ControlPtr],CtrlData	pushworddp <TextLen	jsl InsertParamString	pullword <TextLen	pulllong <TextPtr	pushlongdp <TextPtr	pushworddp <TextLen	pushzptr <Rect	pushword #0	; Left justification;; Re-deref the handle to the control and see which longstattext type we have; (Added SEG 16 Aug 88)	movelong [<theControl],0,<ControlPtr;; Check for LongStatText or LongStatText2, DAN H.;	ldy #CtrlrefCon+2	; where ItemType was stored, DAN H.	lda [<ControlPtr],y	; get ItemType, DAN	H.	and #$7fff	; DAN H.	cmp #LongStatText2	; see if LongStatText2, DAN H.	bne JustLSText	; DAN H.	_LETextBox2	; DAN H.	bra OverLSText	; DAN H.JustLSText	_LETextBoxOverLSText;; Dispose of pointer (actually handle for the created string);	pha	; space for handle	pha	pushlongdp <TextPtr	_FindHandle	_DisposeHandleexit	brl LongStatTextExit********************* Test LongStatText*******************TestLongStatText	movelong #inLongStatText,<RetValue;; Check for LongStatText2, DAN H.;	ldy #CtrlrefCon+2	; where ItemType was stored, DAN H.	lda [<ControlPtr],y	; get ItemType, DAN	H.	and #$7fff	; DAN H.	cmp #LongStatText2	; see if LongStatText2, DAN H.	bne TJustLSText	; DAN H.	movelong #inLongStatText2,<RetValue ; DAN H.TJustLSText	brl LongStatTextExit********************* RecSize LongStatText*******************RecLongStatText;; Returns LongStatTextSIZE;	movelong #LongStatTextSIZE,<RetValue	brl LongStatTextExit	ENDP;            copy  EditLine.asm; LineEdit.asm		 Jean-Charles Mourey	TITLE 'EditLine Item Definition Procedure';___________________________________________________________________________;;       EditLineDefProc;;       input: message:WORD - desired operation;              param:LONG - depends on operation;              theControl:LONG - handle	to control;;      output: RetValue:LONG - depends on operation;____________________________________________________________________________	ENTRY EditLineDefProcEditLineDefProc	PROCControlPtr	equ 0Rect	equ ControlPtr+4Dialog	equ Rect+RECTSIZEhLE	equ Dialog+4TextPtr	equ hLE+4TextLen	equ TextPtr+4OldEditControl	equ TextLen+2FontInfo	equ OldEditControl+4FontHeight	equ FontInfo+8DestRect	equ FontHeight+2SizeLocals	equ DestRect+RECTSIZE	nop	link 10,SizeLocalstheControl	equ inputparam	equ theControl+4CtlMessage	equ param+4RetValue	equ output;; Zeroes out RetValue;	stz <RetValue	stz <RetValue+2;; Check to see which message.  If it is	the RecSize msg then; skip this part which sets port and origin since pointers; in control handle	are not yet valid.;	lda <CtlMessage	cmp #RecSize	beq SkipThisShit;; Derefence Control	Handle;	movelong [<theControl],0,<ControlPtr;; Get a copy of the	enclosing rect;	movelong [<ControlPtr],CtrlRect,<Rect	movelong [<ControlPtr],CtrlRect+4,<Rect+4;; Set Port and origin;	movelong [<ControlPtr],CtrlOwner,<Dialog	pushlongdp <Dialog	_SetPort	lda #0	pha	pha	_SetOrigin;; Get Control Pointer again;	movelong [<theControl],0,<ControlPtrSkipThisShit;; Dispatch;	lda <CtlMessage	asl a	tax	lda >CmdTable,x	pha	rtsCmdTable	DC.W DrawEditLine-1	DC.W EditLineExit-1	DC.W TestEditLine-1	DC.W InitEditLine-1	DC.W DispEditLine-1	DC.W EditLineExit-1	DC.W EditLineExit-1	DC.W EditLineExit-1	DC.W EditLineExit-1	DC.W DrawEditLine-1	; new value fall thru draw routine	DC.W EditLineExit-1	DC.W EditLineExit-1	DC.W RecEditLine-1EditLineExit	ldx #SizeLocals	jmp quitdefproc********************* Draw EditLine*******************DrawEditLine	jsr NormalTextColor;; Draw EditLine enclosing rect;	pushword #BLACK	_SetSolidPenPat;; Frame the surrounding Rect;	pushword #2	pushword #1	_SetPenSize	pushzptr <Rect	_FrameRect	pushword #1	pushword #1	_SetPenSize;; Erase the inner Rect;	pushzptr <Rect	pushword #2	pushword #1	_InsetRect	pushzptr <Rect	_EraseRect;; ReDraws the Line by calling LineEdit;	movelong [<theControl],0,<ControlPtr	pushlong [<ControlPtr],CtrlData ; CtrlData = hLE	_LEUpdate	brl EditLineExit********************* Test EditLine*******************TestEditLine;; Else returns the part Code inEditLine;	movelong #inEditLine,<RetValue;; Get ID of previous active EditLine Item;	movelong [<theControl],0,<ControlPtr	ldy #edittextID-wport	lda [<Dialog],y;; If no previous active item, set the new one active;	beq SetNewEditItem;; If there was one,	compare its ID to the item hit ID;	ldy #iitemid	cmp [<ControlPtr],y;; If same ID, exit directly;	bne GetOldEditLine	brl EditLineExit;; if not same, deactivate old Edit Line	item;GetOldEditLine	tax	pha	; space for control	pha	pushlongdp <Dialog	phx	_GetControlDItem	pulllong <OldEditControl	lda <OldEditControl	bne DeactivateOld***	lda <OldEditControl	lda <OldEditControl+2	;was missing +2 (3-Mar-91 DAL)	beq SetNewEditItemDeactivateOld	movelong [<OldEditControl],0,<ControlPtr	pushlong [<ControlPtr],CtrlData	_LEDeactivate;; Set this EditLine	item as the current	one being edited;SetNewEditItem	movelong [<theControl],0,<ControlPtr	ldy #iitemid	lda [<ControlPtr],y	ldy #edittextID-wport	sta [<Dialog],y	movelong [<ControlPtr],CtrlData,<hLE	lda #0	pha	pha	pushlongdp <hLE	_LESetSelect;; Activate New Edit	Item;	pushlongdp <hLE	_LEActivate	brl EditLineExit********************* Init EditLine*******************InitEditLine;; Get a pointer to the string;	movelong [<ControlPtr],CtrlData,<TextPtr ; points to default string	movelong [<ControlPtr],CtrlValue,<TextLen ; max string length;; Calculate the view rectangle;	pushzptr Rect	pushword #2	pushword #1	_InsetRect;; Calculate the font height;	pushzptr FontInfo	_GetFontInfo	lda <FontInfo	; ascent	clc	adc <FontInfo+2	; descent	adc <FontInfo+6	; leading	sta <FontHeight;; Calculate how much the destRect must be inseted;	movelong <Rect,<DestRect	movelong <Rect+4,<DestRect+4	lda <Rect+y2	; inset = (viewRect.y2 - viewRect.y1	sec	;         - FontHeight)/2	sbc <Rect+y1	sbc <FontHeight	lsr a	tax	pushzptr DestRect	pushword #4	; horizontal inset = 4	phx	; vertical inset computed to center text	_InsetRect;; Create the LineEdit Record;	pha	; space for Line Edit Handle	pha	pushzptr <DestRect	pushzptr <Rect	pushworddp <TextLen	_LENew	pulllong <hLE;; Deactivate it (so	it is created deactivated);	pushlongdp <hLE	_LEDeactivate;; Test if TextPtr is Nil or not;	lda <TextPtr	bne DefaultText	lda <TextPtr+2	beq StorehLE;; Set the edit text	to the string passed as parameter;DefaultText		; 	lda [<TextPtr]	; Get Length byte in TextLen	and #$FF	sta <TextLen	add4 <TextPtr,#1,<TextPtr ; Get pointer	to beginning of text	pushlongdp <TextPtr	pushworddp <TextLen	pushlongdp <hLE	_LESetText;; Store hLE in CtrlData field of item;StorehLE	movelong [<theControl],0,<ControlPtr	ldy #CtrlData	lda <hLE	sta [<ControlPtr],y	iny	iny	lda <hLE+2	sta [<ControlPtr],y;; If there is yet no current edit line item (ie there is yet NO edit line item),; set this one to the current one;	movelong [<ControlPtr],CtrlOwner,<Dialog	ldy #edittextID-wport	lda [<Dialog],y	bne InitExit	pushlongdp <Dialog	ldy #iitemid	lda [<ControlPtr],y	pha	pushword #0	pushword #32767	_SelITextInitExit	brl EditLineExit********************* Disp EditLine*******************DispEditLine;; Test if disposed item is the active one;	movelong [<ControlPtr],CtrlOwner,<Dialog	ldy #edittextID-wport	lda [<Dialog],y;; If no active item, nothing to worry about;	beq DisposeIt;; If there is one, compare its ID to the disposed item ID;	ldy #iitemid	cmp [<ControlPtr],y;; If different ID, nothing to worry about;	bne DisposeIt;; If same ID, clear	the edittextID field;	lda #0	ldy #edittextID-wport	sta [<Dialog],y;; Dispose of hLE;DisposeIt	pushlong [<ControlPtr],CtrlData	_LEDispose;; Allows the Control Manager to continue disposal;	brl EditLineExit********************* RecSize EditLine*******************RecEditLine;; Returns EditLineSIZE;	movelong #EditLineSIZE,<RetValue	brl EditLineExit	ENDP;            copy  DScroll.asm; DScroll.asm		Jean-Charles Mourey	TITLE 'Dialog Scroll Bars action procedure';+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++;;       scroll_action;;      input: partCode:WORD - Selected part.;             theControl:LONG - Handle to control.;;     output: none.;;     function: track the scroll bar and call the dialog scroll bar def proc.;;       MyDialogScrollBar:;;           input: command:WORD;                  dialog:LONG - dialog	the scroll bar is in.;                  ScrollBarID:WORD - item ID of scroll bar.;;          output: result:WORD;;      command: getinitview    = 1	output = init view;               getinittotal   = 2	output = init total;               getinitvalue   = 3	output = init value;               scrolllineup   = 4	output = new value;               scrolllinedown = 5	output = new value;               scrollpageup   = 6	output = new value;               scrollpagedown = 7	output = new value;               scrollthumb    = 8	output = new value;;+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++	ENTRY scroll_actionscroll_action	PROCControlPtr	equ 0DlgScrollAction	equ ControlPtr+4SizeLocals	equ DlgScrollAction+4	nop	link 6,SizeLocalstheControl	equ inputpartCode	equ theControl+4;; Get address of Dialog Scroll Bar Action;	movelong [<theControl],0,<ControlPtr	movelong [<ControlPtr],iScrollBarDef,<DlgScrollAction;; if no action, exit;	lda <DlgScrollAction	bne LetScroll	lda <DlgScrollAction+2	beq exit;; Call the Dialog Scroll Bar Action Procedure;LetScroll		; 	pha	; space for result	lda <PartCode	; command number	cmp #UP_PART	bne isDown	lda #scrolllineup	bra CallItisDown	cmp #DOWN_PART	bne isPageUp	lda #scrolllinedown	bra CallItisPageUp	cmp #UPP_PART	bne isPageDown	lda #scrollpageup	bra CallItisPageDown	cmp #DOWNP_PART	bne isThumb	lda #scrollpagedown	bra CallItisThumb	cmp #THUMB_PART	bne isNothin	lda #scrollthumb	bra CallItisNothin	pla	bra exitCallIt	pha	; push command number	pushlong [<ControlPtr],CtrlOwner ; push	dialog	ldy #iitemid	; push Scroll Bar ID	lda [<ControlPtr],y	pha	lda <DlgScrollAction	ldx <DlgScrollAction+1	jsl long_call	; new value is on stack;; Set new value for	control using result of scroll bar dialog action proc.;	pushlongdp <theControl	_SetCtlValueexit	unlink	rtl	ENDP;            copy  UserItem.asm; UserItem.asm		 Jean-Charles Mourey	TITLE 'UserItem Definition Procedure';___________________________________________________________________________;;       UserItemDefProc;;       input: message:WORD - desired operation;              param:LONG - depends on operation;              theControl:LONG - handle	to control;;      output: RetValue:LONG - depends on operation;;    function: Implements the user item	as a custom control. Calls the user;              item	definition procedure to draw the item.;;        MyItem:;              input: theDialog:LONG - pointer to the dialog's grafport;	  itemID:WORD - ID of item to draw;;             output: none;____________________________________________________________________________	ENTRY UserItemDefProcUserItemDefProc	PROCControlPtr	equ 0Rect	equ ControlPtr+4Dialog	equ Rect+RECTSIZEUserItemProc	equ Dialog+4SizeLocals	equ UserItemProc+4	nop	link 10,SizeLocalstheControl	equ inputparam	equ theControl+4CtlMessage	equ param+4RetValue	equ output;; Zeroes out RetValue;	stz <RetValue	stz <RetValue+2;; Check to see which message.  If it is	the RecSize msg then; skip this part which sets port and origin since pointers; in control handle	are not yet valid.;	lda <CtlMessage	cmp #RecSize	beq SkipThisShit;; Dereference Control Handle;	movelong [<theControl],0,<ControlPtr;; Get pointer to the dialog;	movelong [<ControlPtr],CtrlOwner,<Dialog	pushlongdp <Dialog	_SetPort	lda #0	pha	pha	_SetOrigin;; Dereference Control Handle again;	movelong [<theControl],0,<ControlPtr;; Dispatch message;SkipThisShit	lda <CtlMessage	asl a	tax	lda >CmdTable,x	pha	rtsCmdTable	DC.W DrawUserItem-1	DC.W UserItemExit-1	DC.W TestUserItem-1	DC.W UserItemExit-1	DC.W UserItemExit-1	DC.W UserItemExit-1	DC.W UserItemExit-1	DC.W UserItemExit-1	DC.W UserItemExit-1	DC.W DrawUserItem-1	; new value fall thru draw routine	DC.W UserItemExit-1	DC.W UserItemExit-1	DC.W RecUserItem-1UserItemExit	ldx #SizeLocals	jmp quitdefproc********************* Draw UserItem*******************DrawUserItem;; Call the User Item definition procedure to draw it;	movelong [<ControlPtr],CtrlData,<UserItemProc	lda <UserItemProc	bne CallIt	lda <UserItemProc+2	beq DrawExitCallIt		; 	pushlongdp <Dialog	; pass dialog pointer	ldy #iitemid	;  and item ID	lda [<ControlPtr],y	pha	lda <UserItemProc	ldx <UserItemProc+1	jsl long_callDrawExit	brl UserItemExit********************* Test UserItem*******************TestUserItem	movelong #inUserItem,<RetValue	brl UserItemExit********************* RecSize UserItem*******************RecUserItem;; Returns UserItemSIZE;	movelong #UserItemSIZE,<RetValue	brl UserItemExit	ENDP;            copy  IconItem.asm; IconItem.asm		 Jean-Charles Mourey	TITLE 'IconItem Definition Procedure';___________________________________________________________________________;;       IconItemDefProc;;       input: message:WORD - desired operation;              param:LONG - depends on operation;              theControl:LONG - handle	to control;;      output: RetValue:LONG - depends on operation;;    function: Define an item of type icon and implements it as a;              custom control.;; ======================================================;;  IconHandle: Handle to an IconRecord;;  IconRecord: BoundsRect:RECT - icon rectangle (width must	be multiple of 8);              PixelImage: BYTES - icon	bitmap;; Change History;; 07 Oct 88	Steven Glass;; Only deref the control handle if the message is not recsize.; ======================================================;____________________________________________________________________________	ENTRY IconItemDefProcIconItemDefProc	PROCControlPtr	equ 0Rect	equ ControlPtr+4Dialog	equ Rect+RECTSIZEIconHandle	equ Dialog+4IconPtr	equ IconHandle+4SizeLocals	equ IconPtr+4	nop	link 10,SizeLocalstheControl	equ inputparam	equ theControl+4CtlMessage	equ param+4RetValue	equ output;; Zeroes out RetValue;	stz <RetValue	stz <RetValue+2	lda <CtlMessage	cmp #RecSize	beq SkipThis;; Dereference Control Handle;	movelong [<theControl],0,<ControlPtr;; Get Enclosing Rect;	movelong [<ControlPtr],CtrlRect,<Rect	movelong [<ControlPtr],CtrlRect+4,<Rect+4;; Get Dialog Pointer;	movelong [<ControlPtr],CtrlOwner,<DialogSkipThis;; Dispatch message;	lda <CtlMessage	asl a	tax	lda >CmdTable,x	pha	rtsCmdTable	DC.W DrawIconItem-1	DC.W IconItemExit-1	DC.W TestIconItem-1	DC.W IconItemExit-1	DC.W IconItemExit-1	DC.W IconItemExit-1	DC.W IconItemExit-1	DC.W IconItemExit-1	DC.W IconItemExit-1	DC.W DrawIconItem-1	; new value fall thru draw routine	DC.W IconItemExit-1	DC.W IconItemExit-1	DC.W RecIconItem-1IconItemExit	ldx #SizeLocals	jmp quitdefproc**************************** Draw IconItem***************************DrawIconItem;; Get icon handle, lock it and dereference it;	movelong [<ControlPtr],CtrlData,<IconHandle	pushlongdp <IconHandle	_HLock	movelong [<IconHandle],0,<IconPtr	tsc	; make room on the stack for a loc info	record	sec	; (16 bytes)	sbc #16	tcs	pea 0000	; Push pointer to src loc info record	inc a	pha	pei IconPtr+2	; Push pointer to src rect	pei IconPtr	pei Rect+2	; Push dest loc	pei Rect	PushWord #0	; Push xfer mode	DefineStack	; define the current stack offsetssXferMode	wordsYLoc	wordsXLoc	wordsSrcRectPtr	LONGsSrcLIPtr	LONGLIOffset	block 16	pha	; get current mode from quickdraw.	_GetMasterSCB	pla	and #$0080	; mask off all but mode byte	tax	; save copy in x for later and 	sta LIOffset,s	; put mode into LocInfo	lda IconPtr	; Fill in ImagePtr field of loc info record	clc	; (Image starts 8 bytes from start of icon)	adc #8	sta LIOffset+2,s	lda IconPtr+2	adc #0	sta LIOffset+4,s	ldy #6	; to fill in the width field we calculate width from	lda [IconPtr],y	; src rect	sec	ldy #2	sbc [IconPtr],y	; this is width of src rect	lsr a	; divide by 2 for 320 mode (turns pixels to bytes)	txy	; check mode (saved	in x earlier)	beq ModeIs320	; zero means 320 mode	lsr a	; non-zero means 640 mode so we must divide againModeIs320	sta LIOffset+6,s	; store result in loc info record	lda [IconPtr]	; Finally, we use the rect from the icon as the	sta LIOffset+8,s	; bounds rect in the locinfo record.	ldy #2	lda [IconPtr],y	sta LIOffset+8+2,s	ldy #4	lda [IconPtr],y	sta LIOffset+8+4,s	ldy #6	lda [IconPtr],y	sta LIOffset+8+6,s	_PPToPort	; make the call	tsc	; take the 16 bytes	for the loc info record back off	clc	; the stack	adc #16	tcs;; Unlock icon handle;	pushlongdp <IconHandle	_HUnlock	brl IconItemExit********************* Test IconItem*******************TestIconItem	movelong #inIconItem,<RetValue	brl IconItemExit********************* RecSize IconItem*******************RecIconItem;; Returns IconItemSIZE;	movelong #IconItemSIZE,<RetValue	brl IconItemExit	ENDP;            copy  DUndef.asm; DUndef.asm		Jean-Charles Mourey	TITLE 'Currently unimplemented Calls & Procedures'	ENTRY RESERVEDRESERVED	PROC	rtl	ENDP;; Custom Controls Def Proc;	ENTRY PicItemDefProcPicItemDefProc	PROC	rtl	ENDP************************************************************************ NormalTextColor** Sets the foreground color to black and the background color to* white.** Change History** 07 Jun 88	Steve and Harry** Added today.***********************************************************************NormalTextColor	Proc	pea $0000	_SetForeColor	pea $FFFF	_SetBackColor	rts	ENDP	END